/* ── Format helpers ── */
const fmt = (v, d = 2) => {
  if (v === null || v === undefined || v === '') return '--';
  const n = Number(v);
  if (isNaN(n)) return '--';
  return n.toFixed(d);
};
const pct = (v) => {
  if (v === null || v === undefined || v === '' || isNaN(Number(v))) return '--';
  const n = Number(v);
  return `${n > 0 ? '+' : ''}${n.toFixed(2)}%`;
};
const yuan = (v) => {
  if (v === null || v === undefined || v === '') return '--';
  const n = Number(v);
  if (isNaN(n)) return '--';
  return n.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};
const formatFlow = (v) => {
  if (v === null || v === undefined || v === '' || isNaN(Number(v))) return '--';
  const n = Number(v);
  return `${n > 0 ? '+' : ''}${n.toFixed(2)}亿`;
};

const SIGNAL_META = {
  buy:  { label: '买入',  icon: TrendingUp,  cls: 'badge-buy' },
  sell: { label: '剔除', icon: TrendingDown, cls: 'badge-sell' },
  hold: { label: '观察', icon: Activity,     cls: 'badge-hold' },
};
const SECTOR_META = {
  bull:    { label: '资金入场', cls: 'badge-pull' },
  warn:    { label: '警惕',     cls: 'badge-trend' },
  bear:    { label: '资金出逃', cls: 'badge-sell' },
  neutral: { label: '中性',     cls: 'badge-hold' },
};
const sectorMeta = (tone) => SECTOR_META[tone || 'neutral'] || SECTOR_META.neutral;

/* ── Sub-components ── */

function StatCard({ label, value, icon: Icon, sub, delay = 0 }) {
  return (
    <div className={`spp-glass rounded-xl p-4 fade-in`}
      style={{ animationDelay: `${delay}s` }}>
      <div className="flex items-center justify-between mb-2">
        <span className="text-[11px] font-semibold uppercase tracking-[0.12em]"
          style={{ color: 'var(--text-muted)' }}>{label}</span>
        <div className="flex h-7 w-7 items-center justify-center rounded-lg"
          style={{ background: 'var(--bg-surface)', color: 'var(--text-secondary)' }}>
          <Icon className="h-3.5 w-3.5" />
        </div>
      </div>
      <div className="text-[24px] font-bold font-data tracking-tight" style={{ color: 'var(--text-primary)' }}>
        {value}
      </div>
      {sub && (
        <div className="mt-1 text-[11px] font-data" style={{ color: 'var(--text-secondary)' }}>
          {sub}
        </div>
      )}
    </div>
  );
}

function ScoreBar({ score, size = 'sm' }) {
  const val = Math.min(Math.max(Number(score) || 0, 0), 100);
  const color = val >= 70 ? 'var(--score-high)' : val >= 40 ? 'var(--score-mid)' : 'var(--score-low)';
  const h = size === 'lg' ? 'h-2' : 'h-1.5';
  return (
    <div className="flex items-center gap-2">
      <div className={`${h} rounded-full overflow-hidden flex-1`} style={{ background: 'var(--border)' }}>
        <div className={`${h} rounded-full transition-all duration-700 ease-out`}
          style={{ width: `${val}%`, background: color }} />
      </div>
      <span className="text-[11px] font-bold font-data w-9 text-right" style={{ color }}>
        {fmt(score, 0)}%
      </span>
    </div>
  );
}

function ScoreDot({ score }) {
  const n = Number(score);
  const color = n >= 70 ? 'var(--score-high)' : n >= 40 ? 'var(--score-mid)' : 'var(--score-low)';
  return (
    <span className="inline-flex items-center justify-center w-6 h-6 rounded-lg text-[10px] font-bold text-white shadow-sm"
      style={{ background: color }}>{score}</span>
  );
}

function SignalBadge({ signal, icon: CustomIcon }) {
  const meta = SIGNAL_META[signal] || SIGNAL_META.hold;
  const Icon = CustomIcon || meta.icon;
  return (
    <span className={`inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1 text-[11px] font-bold ${meta.cls}`}>
      <Icon className="h-3 w-3" /> {meta.label}
    </span>
  );
}

function SectorDot({ tone }) {
  const dotColor = tone === 'bull' ? 'var(--green)' : tone === 'bear' ? 'var(--red)' : tone === 'warn' ? 'var(--orange)' : 'var(--text-muted)';
  return (
    <span className="inline-block h-2 w-2 rounded-full flex-shrink-0" style={{ background: dotColor }} />
  );
}

/* ── Adopt Modal ── */
function AdoptModal({ sig, onClose, onConfirm }) {
  const [qty, setQty] = useState(100);
  const [cost, setCost] = useState(sig?.close_price || 0);
  const [tp, setTp] = useState(10.0);
  const [sl, setSl] = useState(5.0);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  useEffect(() => {
    if (sig) { setCost(sig.close_price || 0); setErr(''); }
  }, [sig]);
  if (!sig) return null;
  const submit = async () => {
    setBusy(true); setErr('');
    try {
      await onConfirm({ code: sig.code, name: sig.name, market: sig.market, quantity: qty, avg_cost: Number(cost), take_profit_pct: tp, stop_loss_pct: sl, signal_id: null });
    } catch (e) { setErr(String(e)); }
    finally { setBusy(false); }
  };
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={{ background: 'var(--bg-overlay)' }}>
      <div className="spp-glass-elevated rounded-2xl w-full max-w-md overflow-hidden fade-in">
        <div className="flex items-center justify-between px-6 py-4" style={{ borderBottom: '1px solid var(--border)' }}>
          <div>
            <div className="text-[17px] font-bold" style={{ color: 'var(--text-primary)' }}>买入 {sig.name}</div>
            <div className="mt-0.5 text-[12px] font-data" style={{ color: 'var(--text-muted)' }}>{sig.code}.{sig.market} · ¥{fmt(sig.close_price)}</div>
          </div>
          <button onClick={onClose} className="flex h-8 w-8 items-center justify-center rounded-xl transition-colors hover:bg-[var(--bg-hover)]">
            <X className="h-4 w-4" style={{ color: 'var(--text-muted)' }} />
          </button>
        </div>
        <div className="px-6 py-5 space-y-4">
          {[
            { label: '数量（股）', value: qty, set: setQty, step: 1 },
            { label: '买入价', value: cost, set: setCost, step: 0.01 },
            { label: '止盈 %', value: tp, set: setTp, step: 0.1 },
            { label: '止损 %', value: sl, set: setSl, step: 0.1 },
          ].map((f) => (
            <label key={f.label} className="flex items-center justify-between gap-4">
              <span className="text-sm font-medium" style={{ color: 'var(--text-secondary)' }}>{f.label}</span>
              <input type="number" step={f.step} value={f.value}
                onChange={e => f.set(Number(e.target.value))}
                className="w-36 rounded-xl border px-4 py-2.5 text-right font-data text-sm transition-all"
                style={{ background: 'var(--bg-surface)', borderColor: 'var(--border)', color: 'var(--orange)' }} />
            </label>
          ))}
          {err && <div className="rounded-xl px-4 py-2.5 text-sm font-data badge-sell">{err}</div>}
        </div>
        <div className="flex gap-3 px-6 pb-5">
          <button onClick={onClose}
            className="flex-1 rounded-xl py-3 text-sm font-semibold transition-all spp-glass hover:bg-[var(--bg-hover)]"
            style={{ color: 'var(--text-secondary)' }}>取消</button>
          <button onClick={submit} disabled={busy}
            className="flex-1 rounded-xl py-3 text-sm font-bold text-white disabled:opacity-40 transition-all flex items-center justify-center gap-2"
            style={{ background: 'var(--blue)' }}>
            {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
            确认建仓
          </button>
        </div>
      </div>
    </div>
  );
}

/* ── Section header ── */
function SectionHeader({ title, subtitle, children }) {
  return (
    <div className="flex items-center gap-3 mb-4">
      <div className="h-5 w-0.5 rounded-full flex-shrink-0" style={{ background: 'var(--text-muted)' }} />
      <div className="flex-1 min-w-0">
        <h2 className="text-[15px] font-bold tracking-tight" style={{ color: 'var(--text-primary)' }}>{title}</h2>
        {subtitle && <span className="text-[11px] font-data" style={{ color: 'var(--text-muted)' }}>{subtitle}</span>}
      </div>
      {children}
    </div>
  );
}

/* ── Main page ── */
export default function StrategyPositionPage({ embedded = false } = {}) {
  const [activeNav, setActiveNav] = useState('strategy_position');
  const [signals, setSignals] = useState([]);
  const [positions, setPositions] = useState([]);
  const [sectorSummary, setSectorSummary] = useState([]);
  const [sectorSummaryDate, setSectorSummaryDate] = useState('');
  const [sectorOverview, setSectorOverview] = useState({});
  const [sigDate, setSigDate] = useState('');
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [updatedAt, setUpdatedAt] = useState('');
  const [adopting, setAdopting] = useState(null);
  const [adoptSig, setAdoptSig] = useState(null);
  const [showAllSectors, setShowAllSectors] = useState(false);

  const fetchAll = useCallback(async (silent = false) => {
    if (!silent) setLoading(true); else setRefreshing(true);
    setError('');
    try {
      const [sRes, pRes, sectorRes] = await Promise.all([
        fetch('/api/ops/wave/signals'), fetch('/api/ops/wave/positions'), fetch('/api/ops/wave/sector-summary'),
      ]);
      const sData = await sRes.json(), pData = await pRes.json();
      if (!sData.ok) throw new Error('signals: ' + (sData.detail || 'fail'));
      if (!pData.ok) throw new Error('positions: ' + (pData.detail || 'fail'));
      setSignals(sData.signals || []);
      setSigDate(sData.date || '');
      setPositions(pData.positions || []);
      try {
        const sectorData = await sectorRes.json();
        if (sectorData.ok) { setSectorSummary(sectorData.sectors || []); setSectorOverview(sectorData.summary || {}); setSectorSummaryDate(sectorData.date || ''); }
        else { setSectorSummary([]); setSectorOverview({}); setSectorSummaryDate(''); }
      } catch { setSectorSummary([]); setSectorOverview({}); setSectorSummaryDate(''); }
      setUpdatedAt(new Date().toLocaleTimeString('zh-CN'));
    } catch (e) { setError(String(e)); }
    finally { setLoading(false); setRefreshing(false); }
  }, []);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const runSignalNow = async () => {
    setRefreshing(true);
    try { await fetch('/api/ops/wave/run', { method: 'POST' }); setTimeout(() => fetchAll(true), 4000); }
    catch (e) { setError(String(e)); setRefreshing(false); }
  };

  const handleAdopt = async (payload) => {
    setAdopting(payload.code);
    try {
      const res = await fetch('/api/ops/wave/positions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      const data = await res.json();
      if (!data.ok) throw new Error(data.detail || '开仓失败');
      setAdoptSig(null); await fetchAll(true);
    } finally { setAdopting(null); }
  };

  const totalUnrealized = positions.reduce((s, p) => s + Number(p.unrealized_pnl || 0), 0);
  const buyCount = signals.filter(s => s.signal === 'buy').length;
  const sellCount = signals.filter(s => s.signal === 'sell').length;
  const sectorMap = useMemo(() => { const m = {}; sectorSummary.forEach(i => { m[i.sector_name] = i; }); return m; }, [sectorSummary]);

  const statCards = [
    { label: '信号日期', value: sigDate || '--', icon: Zap, accent: 'orange' },
    { label: '买入信号', value: buyCount, icon: TrendingUp, accent: 'green',
      sub: `${buyCount + sellCount > 0 ? ((buyCount / (buyCount + sellCount) * 100).toFixed(0)) : 0}% 占比` },
    { label: '剔除信号', value: sellCount, icon: TrendingDown, accent: 'red',
      sub: `${buyCount + sellCount > 0 ? ((sellCount / (buyCount + sellCount) * 100).toFixed(0)) : 0}% 占比` },
    { label: '当前持仓', value: `${positions.length} 只`, icon: DollarSign, accent: 'blue',
      sub: totalUnrealized !== 0 ? `${totalUnrealized >= 0 ? '+' : ''}${yuan(totalUnrealized)}` : '无浮动盈亏' },
  ];

  const topSectors = [
    { key: 'top_inflow', title: '净流入最强', icon: ArrowUpRight, empty: '暂无数据' },
    { key: 'top_outflow', title: '净流出最强', icon: ArrowDownRight, empty: '暂无数据' },
    { key: 'strongest', title: '综合强度最高', icon: Shield, empty: '暂无数据' },
  ];

  return (
    <div className={`strategy-position-page ${embedded ? '' : 'min-h-screen'}`}
      style={{ background: 'var(--bg-page)', color: 'var(--text-primary)' }}>
      <style>{_css}</style>

      <div className={embedded ? 'mx-auto flex max-w-[1440px]' : 'mx-auto flex min-h-screen max-w-[1440px]'}>
        {!embedded && (
          <CockpitSidebar collapsed={false} onToggleCollapsed={() => {}} activeNav={activeNav} updatedAt={updatedAt} status="波段" />
        )}

        <main className={`flex-1 text-[14px] leading-6 ${embedded ? '' : 'space-y-5 px-6 py-5 lg:px-8'}`}>
          {!embedded && (
            <HeaderBar
              date={sigDate || new Date().toISOString().slice(0, 10)} updatedAt={updatedAt}
              dataStatus="最新" viewMode="LIVE" titleOverride="波段信号 · 策略持仓" phaseTagOverride="波段"
              showDatePicker={false}
              actions={
                <button onClick={runSignalNow} disabled={refreshing}
                  className="flex items-center gap-2 rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-4 py-2.5 text-xs font-medium tracking-wider text-[var(--text-primary)] transition-all hover:bg-[var(--bg-hover)] disabled:cursor-not-allowed disabled:opacity-70">
                  <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? 'animate-spin' : ''}`} />
                  {refreshing ? '执行中...' : '立即跑波段'}
                </button>
              }
            />
          )}

          {/* ======== 统计卡片 ======== */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {statCards.map((card, i) => (
              <StatCard key={card.label} {...card} delay={i * 0.06} />
            ))}
          </div>

          {/* ======== 板块态势 ======== */}
          <div className="spp-divider" />

          <section>
            <SectionHeader title="板块态势" subtitle={sectorSummaryDate || sigDate || '--'}>
              <div className="flex items-center gap-1.5">
                {[
                  { tone: 'bull', val: sectorOverview.bull ?? 0 },
                  { tone: 'warn', val: sectorOverview.warn ?? 0 },
                  { tone: 'bear', val: sectorOverview.bear ?? 0 },
                  { tone: 'neutral', val: sectorOverview.neutral ?? 0 },
                ].map(({ tone, val }) => (
                  <span key={tone}
                    className={`inline-flex items-center gap-1 rounded-lg px-2 py-0.5 text-[10px] font-bold ${sectorMeta(tone).cls}`}>
                    <SectorDot tone={tone} />
                    {val}
                  </span>
                ))}
              </div>
            </SectionHeader>

            {/* 三大核心板块 */}
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
              {topSectors.map(({ key, title, icon: TIcon, empty }, i) => {
                const item = sectorOverview[key];
                if (!item) {
                  return (
                    <div key={key} className="spp-glass rounded-2xl p-6 text-center fade-in"
                      style={{ animationDelay: `${i * 0.08}s` }}>
                      <TIcon className="mx-auto mb-2 h-5 w-5" style={{ color: 'var(--text-muted)' }} />
                      <div className="text-[10px] uppercase tracking-[0.16em] font-semibold" style={{ color: 'var(--text-muted)' }}>{title}</div>
                      <div className="mt-1 text-sm font-data" style={{ color: 'var(--text-muted)' }}>{empty}</div>
                    </div>
                  );
                }
                const meta = sectorMeta(item.tone);
                return (
                  <div key={key} className="spp-glass rounded-2xl overflow-hidden fade-in spp-hover"
                    style={{ animationDelay: `${i * 0.08}s` }}>
                    {/* Top accent bar */}
                    <div className="h-1 w-full" style={{ background: `var(--${item.tone === 'bull' ? 'green' : item.tone === 'bear' ? 'red' : item.tone === 'warn' ? 'orange' : 'border'})` }} />
                    <div className="p-5">
                      <div className="flex items-start justify-between mb-4">
                        <div className="flex items-center gap-3">
                          <div className={`flex h-10 w-10 items-center justify-center rounded-xl text-sm ${meta.cls}`}>
                            <TIcon className="h-5 w-5" />
                          </div>
                          <div>
                            <div className="text-[10px] font-semibold uppercase tracking-[0.16em]" style={{ color: 'var(--text-muted)' }}>{title}</div>
                            <div className="text-base font-bold mt-0.5" style={{ color: 'var(--text-primary)' }}>{item.sector_name}</div>
                          </div>
                        </div>
                        <span className={`inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1 text-[10px] font-bold ${meta.cls}`}>
                          <SectorDot tone={item.tone} />
                          {meta.label}
                        </span>
                      </div>

                      <div className="grid grid-cols-2 gap-3">
                        <div className="spp-surface rounded-xl p-3">
                          <div className="text-[10px] font-semibold uppercase tracking-[0.12em] mb-1" style={{ color: 'var(--text-muted)' }}>资金流向</div>
                          <div className="text-lg font-bold font-data text-up">{formatFlow(item.net_amount)}</div>
                        </div>
                        <div className="spp-surface rounded-xl p-3">
                          <div className="text-[10px] font-semibold uppercase tracking-[0.12em] mb-1" style={{ color: 'var(--text-muted)' }}>涨跌幅</div>
                          <div className={`text-lg font-bold font-data ${Number(item.change_pct) >= 0 ? 'text-up' : 'text-down'}`}>
                            {pct(item.change_pct)}
                          </div>
                        </div>
                      </div>

                      {(item.lead_stock || item.lead_change != null) && (
                        <div className="mt-3 flex items-center gap-3 text-xs rounded-xl spp-surface px-3 py-2.5">
                          {item.lead_stock && (
                            <>
                              <span style={{ color: 'var(--text-secondary)' }}>领涨</span>
                              <span className="font-semibold" style={{ color: 'var(--orange)' }}>{item.lead_stock}</span>
                            </>
                          )}
                          {item.lead_change != null && (
                            <span className="font-data text-up font-bold">{pct(item.lead_change)}</span>
                          )}
                        </div>
                      )}

                      <div className="mt-2.5 text-[11px] leading-relaxed font-data italic"
                        style={{ color: 'var(--text-muted)' }}>
                        "{item.reason}"
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* 板块列表 */}
            {sectorSummary.length > 0 && (
              <div className="mt-4">
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
                  {sectorSummary.slice(0, showAllSectors ? undefined : 6).map((item, idx) => {
                    const meta = sectorMeta(item.tone);
                    return (
                      <div key={item.sector_name} className="spp-glass rounded-xl p-4 fade-in spp-hover"
                        style={{ animationDelay: `${idx * 0.03}s` }}>
                        <div className="flex items-center justify-between mb-3">
                          <div className="flex items-center gap-2.5">
                            <SectorDot tone={item.tone} />
                            <span className="text-sm font-bold" style={{ color: 'var(--text-primary)' }}>{item.sector_name}</span>
                          </div>
                          <span className={`inline-flex items-center gap-1.5 rounded-lg px-2 py-0.5 text-[10px] font-bold ${meta.cls}`}>
                            {meta.label}
                          </span>
                        </div>
                        <div className="flex items-center gap-4 text-[11px] font-data mb-3" style={{ color: 'var(--text-muted)' }}>
                          <span className="flex items-center gap-1.5">
                            <Layers className="h-3 w-3" /> {item.signal_count || 0} 信号
                          </span>
                          <span style={{ color: 'var(--border)' }}>|</span>
                          <span className="flex items-center gap-1.5">
                            <Eye className="h-3 w-3" /> {item.position_count || 0} 持仓
                          </span>
                        </div>
                        <div className="spp-divider-light" />
                        <div className="flex items-center justify-between pt-3">
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] font-semibold uppercase tracking-[0.12em]" style={{ color: 'var(--text-muted)' }}>资金</span>
                            <span className="font-bold font-data text-sm text-up">{formatFlow(item.net_amount)}</span>
                          </div>
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] font-semibold uppercase tracking-[0.12em]" style={{ color: 'var(--text-muted)' }}>涨跌</span>
                            <span className={`font-bold font-data text-sm ${Number(item.change_pct) >= 0 ? 'text-up' : 'text-down'}`}>
                              {pct(item.change_pct)}
                            </span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
                {sectorSummary.length > 6 && (
                  <div className="mt-4 text-center">
                    <button onClick={() => setShowAllSectors(!showAllSectors)}
                      className={`inline-flex items-center gap-1.5 rounded-xl border px-4 py-2 text-[11px] font-semibold font-data tracking-wider uppercase transition-all hover:bg-[var(--bg-hover)]`}
                      style={{ borderColor: 'var(--border)', color: 'var(--orange)' }}>
                      {showAllSectors ? (
                        <><ChevronUp className="h-3 w-3" /> 收起</>
                      ) : (
                        <><ChevronDown className="h-3 w-3" /> 展开全部 {sectorSummary.length} 个板块</>
                      )}
                    </button>
                  </div>
                )}
              </div>
            )}
          </section>

          {error && (
            <div className="flex items-center gap-2 rounded-xl px-4 py-3 text-sm font-data badge-sell">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}

          {/* ======== 波段信号表格 ======== */}
          <div className="spp-divider" />

          <section>
            <SectionHeader title="波段信号" subtitle={`${signals.length} 条信号`} />

            {loading ? (
              <div className="spp-glass rounded-2xl flex items-center justify-center p-20 text-base font-data" style={{ color: 'var(--text-muted)' }}>
                <Loader2 className="mr-3 h-6 w-6 animate-spin" style={{ color: 'var(--blue)' }} />
                加载中...
              </div>
            ) : signals.length === 0 ? (
              <div className="spp-glass rounded-2xl p-16 text-center">
                <BarChart2 className="mx-auto mb-3 h-10 w-10" style={{ color: 'var(--text-muted)' }} />
                <p className="text-base font-semibold" style={{ color: 'var(--text-secondary)' }}>暂无波段信号</p>
                <p className="mt-1 text-sm font-data" style={{ color: 'var(--text-muted)' }}>点击右上角「立即跑波段」生成今日算法输出</p>
              </div>
            ) : (
              <div className="spp-glass rounded-2xl overflow-hidden">
                <div className="overflow-x-auto scrollbar-thin">
                  <table className="w-full min-w-[1200px] text-left">
                    <thead>
                      <tr className="text-[10px] font-semibold uppercase tracking-[0.12em]"
                        style={{ color: 'var(--text-muted)', background: 'var(--bg-surface)' }}>
                        <th className="px-4 py-3.5 rounded-tl-xl">股票</th>
                        <th className="px-4 py-3.5">板块</th>
                        <th className="px-4 py-3.5 text-center">信号</th>
                        <th className="px-4 py-3.5 text-right">现价</th>
                        <th className="px-4 py-3.5 text-right">MA5</th>
                        <th className="px-4 py-3.5 text-right">MA10</th>
                        <th className="px-4 py-3.5 text-right">涨跌幅</th>
                        <th className="px-4 py-3.5 text-right">RSI</th>
                        <th className="px-4 py-3.5 text-right">量比</th>
                        <th className="px-4 py-3.5 text-right" style={{ minWidth: 130 }}>置信度</th>
                        <th className="px-4 py-3.5">信号原因</th>
                        <th className="px-4 py-3.5 text-center rounded-tr-xl">操作</th>
                      </tr>
                    </thead>
                    <tbody>
                      {signals.map((sig, idx) => {
                        const meta = SIGNAL_META[sig.signal] || SIGNAL_META.hold;
                        const Icon = meta.icon;
                        const sector = sectorMap[sig.industry] || null;
                        const sectorMeta_ = sectorMeta(sector?.tone);
                        const isBuy = sig.signal === 'buy';
                        const isSell = sig.signal === 'sell';
                        return (
                          <tr key={sig.id || sig.code || idx}
                            className="text-[13px] font-data leading-6 fade-in spp-hover"
                            style={{
                              borderBottom: '1px solid var(--border-light)',
                              animationDelay: `${idx * 0.025}s`,
                            }}>
                            <td className="px-4 py-3">
                              <div className="flex items-center gap-3">
                                {/* Signal indicator line */}
                                <div className={`w-0.5 h-9 rounded-full flex-shrink-0 ${
                                  isBuy ? '' : isSell ? '' : ''
                                }`} style={{
                                  background: isBuy ? 'var(--green)' : isSell ? 'var(--red)' : 'var(--border)'
                                }} />
                                <div>
                                  <div className="text-[14px] font-bold leading-tight" style={{ color: 'var(--text-primary)' }}>
                                    {sig.name}
                                  </div>
                                  <div className="text-[10px] mt-0.5 font-normal" style={{ color: 'var(--text-muted)' }}>
                                    {sig.code}.{sig.market}
                                  </div>
                                </div>
                              </div>
                            </td>
                            <td className="px-4 py-3">
                              <div className="flex items-center gap-1.5 flex-wrap">
                                <span style={{ color: 'var(--text-secondary)' }}>{sig.industry || '--'}</span>
                                {sector && (
                                  <span className={`inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-bold ${sectorMeta_.cls}`}>
                                    {sectorMeta_.label}
                                  </span>
                                )}
                              </div>
                            </td>
                            <td className="px-4 py-3 text-center">
                              <span className={`inline-flex items-center gap-1 rounded-lg px-2.5 py-1 text-[11px] font-bold ${meta.cls}`}>
                                <Icon className="h-3 w-3" /> {meta.label}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-right font-semibold">
                              <span className={Number(sig.change_pct) >= 0 ? 'text-up' : 'text-down'}>{fmt(sig.close_price)}</span>
                            </td>
                            <td className="px-4 py-3 text-right" style={{ color: 'var(--text-secondary)' }}>{fmt(sig.ma5)}</td>
                            <td className="px-4 py-3 text-right" style={{ color: 'var(--text-secondary)' }}>{fmt(sig.ma10)}</td>
                            <td className={`px-4 py-3 text-right font-semibold ${Number(sig.change_pct) >= 0 ? 'text-up' : 'text-down'}`}>
                              {pct(sig.change_pct)}
                            </td>
                            <td className="px-4 py-3 text-right font-data" style={{ color: 'var(--text-secondary)' }}>{fmt(sig.rsi6)}</td>
                            <td className="px-4 py-3 text-right font-data" style={{ color: 'var(--text-secondary)' }}>{fmt(sig.volume_ratio)}</td>
                            <td className="px-4 py-3 text-right">
                              <ScoreBar score={sig.confidence} />
                            </td>
                            <td className="max-w-[220px] px-4 py-3 text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>
                              <span className="line-clamp-2" title={sig.reason}>{sig.reason}</span>
                            </td>
                            <td className="px-4 py-3 text-center">
                              {isBuy ? (
                                <button onClick={() => setAdoptSig(sig)}
                                  disabled={adopting === (sig.id || sig.code)}
                                  className="inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-[11px] font-bold tracking-wider uppercase badge-buy disabled:opacity-40 transition-all hover:shadow-sm">
                                  {adopting === (sig.id || sig.code)
                                    ? <Loader2 className="h-3 w-3 animate-spin" />
                                    : <Check className="h-3 w-3" />}
                                  采纳
                                </button>
                              ) : isSell ? (
                                <span className="inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-[11px] font-semibold tracking-wider uppercase badge-sell">
                                  <TrendingDown className="h-3 w-3" /> 剔除
                                </span>
                              ) : (
                                <span className="inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-[11px] font-medium" style={{ color: 'var(--text-muted)', background: 'var(--bg-surface)' }}>
                                  <Activity className="h-3 w-3" /> 观察
                                </span>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </section>

        </main>
      </div>

      {adoptSig && (
        <AdoptModal sig={adoptSig} onClose={() => setAdoptSig(null)} onConfirm={async (payload) => { await handleAdopt(payload); }} />
      )}
    </div>
  );
}
