/**
 * 外部数据平台快速链接标签
 * 在股票代码旁边显示新浪/东方财富/同花顺的小图标链接
 */
import { getSinaUrl, getEastMoneyUrl, getTHSUrl } from '../utils/stockLink';

function LinkBadge({ href, label, color, icon }) {
  if (!href) return null;
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      onClick={(e) => e.stopPropagation()}
      className="inline-flex items-center gap-0.5 rounded px-1 py-0 text-[10px] font-medium opacity-60 hover:opacity-100 transition-opacity"
      style={{ color }}
      title={label}
    >
      {icon}{label}
    </a>
  );
}

export default function StockLinks({ code, size = 'sm' }) {
  const sina = getSinaUrl(code);
  const eastmoney = getEastMoneyUrl(code);
  const ths = getTHSUrl(code);

  if (!sina && !eastmoney && !ths) return null;

  const gap = size === 'md' ? 'gap-1.5' : 'gap-1';

  return (
    <span className={`inline-flex items-center ${gap} ml-1`}>
      <LinkBadge href={sina} label="新浪" color="#e6162d" icon="📰" />
      <LinkBadge href={eastmoney} label="东财" color="#3b82f6" icon="📈" />
      <LinkBadge href={ths} label="同花" color="#22c55e" icon="📊" />
    </span>
  );
}
