const API_BASE = '';

function cn(...classes) { return classes.filter(Boolean).join(' '); }

function formatNumber(n) {
  if (n == null) return '-';
  if (n >= 1e8) return `${(n / 1e8).toFixed(1)}亿`;
  if (n >= 1e4) return `${(n / 1e4).toFixed(1)}万`;
  return String(n);
}

function pctColor(v) {
  if (v == null) return 'text-[var(--text-secondary)]';
  if (v > 0) return 'text-rose-600';
  if (v < 0) return 'text-emerald-600';
  return 'text-[var(--text-secondary)]';
}

function freshBadge(is_fresh, days_behind) {
  if (days_behind <= 0) return { label: '最新', cls: 'bg-emerald-50 text-emerald-600 border-emerald-200' };
  if (is_fresh) return { label: `${days_behind}天前`, cls: 'bg-emerald-50 text-emerald-600 border-emerald-200' };
  if (days_behind <= 7) return { label: `${days_behind}天前`, cls: 'bg-amber-50 text-amber-600 border-amber-200' };
  return { label: `${days_behind}天前`, cls: 'bg-rose-50 text-rose-600 border-rose-200' };
}

