/**
 * 通用格式化工具
 */

/** 格式化百分比: +12.34% / -5.67% */
export function fmtPct(val) {
  if (val == null || isNaN(Number(val))) return '--';
  const n = Number(val);
  const sign = n >= 0 ? '+' : '';
  return `${sign}${n.toFixed(2)}%`;
}

/** 将妙想API的整数价格转为带小数价格 */
export function fmtPrice(price, dec = 2) {
  if (price == null) return '--';
  return (Number(price) / Math.pow(10, dec)).toFixed(dec);
}

/** 格式化金额: 元 -> 万/亿 */
export function fmtMoney(val) {
  if (val == null || isNaN(Number(val))) return '--';
  const n = Number(val);
  if (Math.abs(n) >= 100000000) return `${(n / 100000000).toFixed(2)}亿`;
  if (Math.abs(n) >= 10000) return `${(n / 10000).toFixed(2)}万`;
  return n.toFixed(2);
}

/** 格式化数量: 加逗号 */
export function fmtNum(val) {
  if (val == null) return '--';
  return Number(val).toLocaleString('zh-CN');
}

/** 格式化仓位: 67.64% */
export function fmtRatio(val) {
  if (val == null) return '--';
  return `${Number(val).toFixed(2)}%`;
}

/** 涨跌幅颜色 class */
export function pctColor(val) {
  const n = Number(val);
  if (n > 0) return 'text-red-400';
  if (n < 0) return 'text-green-400';
  return 'text-[var(--text-muted)]';
}

/** 涨跌幅背景色 class (浅色) */
export function pctBgColor(val) {
  const n = Number(val);
  if (n > 0) return 'bg-red-50';
  if (n < 0) return 'bg-green-50';
  return 'bg-[var(--bg-surface)]';
}
