export const ROBOT_BY_ID = Object.fromEntries(
  ROBOT_REGISTRY.map((robot) => [robot.id, robot])
);

export const ROBOT_IDS = ROBOT_REGISTRY.map((robot) => robot.id);

export const DEFAULT_CUSTOM_STRATEGY_KEYS = ROBOT_REGISTRY.map((robot) => robot.key);

export const CUSTOM_STRATEGY_OPTIONS = ROBOT_REGISTRY.map((robot) => ({
  value: robot.key,
  label: robot.displayName,
}));

function normalizePayload(payload) {
  if (!payload || typeof payload !== 'object') return {};
  if (payload.data && typeof payload.data === 'object') return payload.data;
  if (payload.stocks && Array.isArray(payload.stocks)) return payload;
  if (payload.robot && payload.name && payload.count && !payload.stocks) return {};
  return {};
}

function getFirstStock(payload, stocks = []) {
  const candidate = Array.isArray(stocks) && stocks.length > 0 ? stocks[0] : null;
  if (candidate && typeof candidate === 'object') return candidate;

  const normalized = normalizePayload(payload);
  const fallback = normalized.stocks || normalized.results || [];
  const first = Array.isArray(fallback) && fallback.length > 0 ? fallback[0] : null;
  return first && typeof first === 'object' ? first : {};
}

export function getRobotMeta(robotId) {
  return ROBOT_BY_ID[robotId] || null;
}

export function getRobotDisplayLabel(robotId, apiData) {
  // 优先用 API 返回的 display_name
  if (apiData?.display_name) return apiData.display_name;
  const meta = getRobotMeta(robotId);
  return meta?.displayName || meta?.name || robotId;
}

export function formatChangePct(value) {
  if (value === null || value === undefined || value === '') return '--';
  const num = Number(value);
  if (Number.isNaN(num)) return '--';
  return `${num >= 0 ? '+' : ''}${num.toFixed(2)}%`;
}

export function resolveSignalDate(payload, stocks = []) {
  const normalized = normalizePayload(payload);
  for (const field of DATE_FIELD_CANDIDATES) {
    const raw = normalized?.[field] ?? payload?.[field];
    if (raw) return String(raw).slice(0, 10);
  }
  const firstStock = getFirstStock(payload, stocks);
  for (const field of DATE_FIELD_CANDIDATES) {
    const raw = firstStock?.[field];
    if (raw) return String(raw).slice(0, 10);
  }
  return '';
}

export function extractRobotStocks(robotId, payload) {
  const normalized = normalizePayload(payload);

  if (robotId === 'robot-7') {
    const qinglong = normalized.qinglong || [];
    const baihu = normalized.baihu || [];
    // 如果 API 返回的是扁平 stocks（无 qinglong/baihu 子结构），则直接用 stocks
    if (qinglong.length === 0 && baihu.length === 0) {
      const flat = normalized.stocks || [];
      return Array.isArray(flat) ? flat.filter((item) => item && typeof item === 'object') : [];
    }
    return [...qinglong, ...baihu].filter((item) => item && typeof item === 'object');
  }

  if (robotId === 'robot-11') {
    const results = normalized.stocks || normalized.results || payload?.stocks || payload?.results || [];
    return Array.isArray(results) ? results.filter((item) => item && typeof item === 'object') : [];
  }

  const stocks = normalized.stocks || payload?.stocks || [];
  if (Array.isArray(stocks)) {
    return stocks.filter((item) => item && typeof item === 'object');
  }

  return [];
}
