import { useState } from 'react';
import { X, ShoppingCart, Loader2, TrendingUp } from 'lucide-react';
import { useMockTrade } from '../../hooks/useMockTrade';
import { extractRobotStocks, formatChangePct, getRobotDisplayLabel } from '../../lib/robotRegistry';

export default function StrategyDetailModal({ robot, data, onClose }) {
  const { loading: tradeLoading, result: tradeResult, error: tradeError, buyStock, clearResult } = useMockTrade();
  const [selectedStock, setSelectedStock] = useState(null);
  const [buyPrice, setBuyPrice] = useState('');
  const [buyQuantity, setBuyQuantity] = useState('');
  const [useMarketPrice, setUseMarketPrice] = useState(false);

  const handleBuy = async () => {
    if (!selectedStock || !buyQuantity) return;

    const price = useMarketPrice ? 0 : parseFloat(buyPrice);
    await buyStock({
      stockCode: selectedStock.code,
      price,
      quantity: parseInt(buyQuantity),
      useMarketPrice,
    });
  };

  const getStocks = () => {
    if (!data) return [];
    return extractRobotStocks(robot, data);
  };

  const stocks = getStocks();

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl w-full max-w-4xl max-h-[90vh] overflow-hidden shadow-2xl">
        {/* 头部 */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)] bg-[var(--bg-surface)]">
          <div className="flex items-center gap-2">
            <TrendingUp className="w-4 h-4 text-cyan-600" />
            <span className="text-sm font-bold text-[var(--text-primary)]">{getRobotDisplayLabel(robot)} 策略明细</span>
          </div>
          <button onClick={onClose} className="p-1 text-[var(--text-secondary)] hover:text-[var(--text-secondary)]">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* 股票列表 */}
        <div className="overflow-y-auto max-h-[55vh] p-4">
          {stocks.length === 0 ? (
            <div className="text-center py-12 text-[var(--text-secondary)] text-lg">暂无符合条件的股票</div>
          ) : (
            <div className="space-y-3">
              {stocks.map((stock, idx) => (
                <div
                  key={idx}
                  className={`flex items-center justify-between p-4 rounded-lg border transition-colors ${
                    selectedStock?.code === stock.code
                      ? 'border-cyan-500 bg-cyan-950/20'
                      : 'border-[var(--border-color)] bg-[var(--bg-surface)] hover:border-[var(--border-color)]'
                  }`}
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-3">
                      <span className="text-lg font-bold text-[var(--text-primary)]">{stock.name}</span>
                      <span className="text-sm font-mono text-[var(--text-secondary)]">{stock.code}</span>
                    </div>
                    <div className="flex items-center gap-4 mt-2 text-sm text-[var(--text-secondary)]">
                      {stock.score !== undefined && <span className="text-amber-600 font-bold">评分: {stock.score}分</span>}
                      {stock.close !== undefined && stock.close !== null && !Number.isNaN(Number(stock.close)) && (
                        <span className="text-cyan-600 font-bold">股价: ¥{Number(stock.close).toFixed(2)}</span>
                      )}
                      {formatChangePct(stock.change_pct ?? stock.pct) !== '--' && (
                        <span className={`font-bold ${(stock.change_pct ?? stock.pct ?? 0) >= 0 ? 'text-emerald-600' : 'text-rose-400'}`}>
                          当日涨幅: {formatChangePct(stock.change_pct ?? stock.pct)}
                        </span>
                      )}
                      {stock.net_inflow !== undefined && <span className="text-emerald-600 font-bold">净流入: {stock.net_inflow.toFixed(0)}万</span>}
                      {stock.net_buy !== undefined && <span className="text-purple-600 font-bold">净买: {stock.net_buy.toFixed(0)}万</span>}
                      {stock.theme && <span className="text-cyan-600 font-bold">题材: {stock.theme}</span>}
                    </div>
                  </div>
                  <button
                    onClick={() => setSelectedStock(stock)}
                    className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors ${
                      selectedStock?.code === stock.code
                        ? 'bg-cyan-600 text-white'
                        : 'bg-[var(--bg-hover)] text-[var(--text-secondary)] hover:bg-[var(--bg-hover)]'
                    }`}
                  >
                    <ShoppingCart className="w-4 h-4" />
                    买入
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* 买入表单 */}
        {selectedStock && (
          <div className="border-t border-[var(--border-color)] p-4 bg-[var(--bg-surface)]">
            <div className="text-sm font-bold text-[var(--text-primary)] mb-3">
              买入 {selectedStock.name} ({selectedStock.code})
            </div>

            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <label className="text-xs text-[var(--text-secondary)] w-16">价格:</label>
                <input
                  type="number"
                  value={buyPrice}
                  onChange={(e) => setBuyPrice(e.target.value)}
                  disabled={useMarketPrice}
                  placeholder="价格"
                  className="flex-1 bg-[var(--bg-card)] border border-[var(--border-color)] rounded px-3 py-2 text-sm text-[var(--text-primary)] disabled:opacity-50"
                />
                <label className="flex items-center gap-1 text-xs text-[var(--text-secondary)]">
                  <input
                    type="checkbox"
                    checked={useMarketPrice}
                    onChange={(e) => setUseMarketPrice(e.target.checked)}
                    className="rounded"
                  />
                  市价
                </label>
              </div>

              <div className="flex items-center gap-2">
                <label className="text-xs text-[var(--text-secondary)] w-16">数量(股):</label>
                <input
                  type="number"
                  value={buyQuantity}
                  onChange={(e) => setBuyQuantity(e.target.value)}
                  placeholder="100的整数倍"
                  className="flex-1 bg-[var(--bg-card)] border border-[var(--border-color)] rounded px-3 py-2 text-sm text-[var(--text-primary)]"
                />
              </div>

              {tradeResult && (
                <div className="p-2 rounded bg-emerald-50 border border-emerald-200 text-xs text-emerald-600">
                  买入成功！委托号: {tradeResult.data?.orderId || '已提交'}
                </div>
              )}

              {tradeError && (
                <div className="p-2 rounded bg-red-50 border border-red-200 text-xs text-red-600">
                  {tradeError}
                </div>
              )}

              <button
                onClick={handleBuy}
                disabled={tradeLoading || (!buyPrice && !useMarketPrice) || !buyQuantity}
                className="w-full py-2.5 bg-cyan-600 hover:bg-cyan-500 disabled:bg-[var(--bg-hover)] disabled:text-[var(--text-secondary)] rounded-lg text-sm font-bold text-white flex items-center justify-center gap-2"
              >
                {tradeLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShoppingCart className="w-4 h-4" />}
                确认买入
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
