import { useState } from 'react';

const API_URL = 'https://mkapi2.dfcfs.com/finskillshub/api/claw/mockTrading/trade';

export function useMockTrade() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const buyStock = async ({ stockCode, price, quantity, useMarketPrice = false }) => {
    setLoading(true);
    setError('');
    setResult(null);

    try {
      const apiKey = import.meta.env.VITE_MX_APIKEY || 'mkt_9Pxb32QtRzVbHvOI6E1TVUMkEoyvOMr-aN4ZMq2FAvg';

      const response = await fetch(API_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'apikey': apiKey,
        },
        body: JSON.stringify({
          type: 'buy',
          stockCode: stockCode.replace(/^(sh|sz)/, ''), // 去掉前缀
          price: price,
          quantity: parseInt(quantity),
          useMarketPrice,
        }),
      });

      const data = await response.json();

      if (data.code === '200' || data.code === 200) {
        setResult(data);
        return { success: true, data };
      } else {
        setError(data.message || '买入失败');
        return { success: false, error: data.message };
      }
    } catch (err) {
      const errorMsg = err.message || '网络错误';
      setError(errorMsg);
      return { success: false, error: errorMsg };
    } finally {
      setLoading(false);
    }
  };

  const sellStock = async ({ stockCode, price, quantity, useMarketPrice = false }) => {
    setLoading(true);
    setError('');
    setResult(null);

    try {
      const apiKey = import.meta.env.VITE_MX_APIKEY || 'mkt_9Pxb32QtRzVbHvOI6E1TVUMkEoyvOMr-aN4ZMq2FAvg';

      const response = await fetch(API_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'apikey': apiKey,
        },
        body: JSON.stringify({
          type: 'sell',
          stockCode: stockCode.replace(/^(sh|sz)/, ''),
          price: price,
          quantity: parseInt(quantity),
          useMarketPrice,
        }),
      });

      const data = await response.json();

      if (data.code === '200' || data.code === 200) {
        setResult(data);
        return { success: true, data };
      } else {
        setError(data.message || '卖出失败');
        return { success: false, error: data.message };
      }
    } catch (err) {
      const errorMsg = err.message || '网络错误';
      setError(errorMsg);
      return { success: false, error: errorMsg };
    } finally {
      setLoading(false);
    }
  };

  const clearResult = () => {
    setResult(null);
    setError('');
  };

  return {
    loading,
    result,
    error,
    buyStock,
    sellStock,
    clearResult,
  };
}
