import { createContext, useContext, useState, useCallback } from 'react';
import { URL_TAB_MAP } from '../constants/routeMap';

/**
 * Shared tab definitions — all three markets use the same tab structure.
 * Tab IDs and paths are identical; the active `market` state drives data fetching.
 */
const SHARED_TABS = [
  {
    group: '复盘分析',
    items: [
      { id: 'theme', label: '题材复盘', path: '/theme-review' },
    ],
  },
  {
    group: '策略执行',
    items: [
      { id: 'stock_monitor', label: '选股持仓', path: '/stock-monitor' },
      { id: 'stock_analysis', label: '选股分析', path: '/stock-analysis' },
      { id: 'strategies', label: '策略信号', path: '/robot-strategies' },
      { id: 'screener', label: '智能选股', path: '/stock-screener' },
      { id: 'mock_trading', label: '模拟交易', path: '/mock-trading' },
      { id: 'wave', label: '波段信号', path: '/strategy-position' },
    ],
  },
];

const US_TABS = [
  {
    group: '美股',
    items: [
      { id: 'us_overview', label: '行情总览', path: '/us-market' },
      { id: 'us_monitor', label: '选股监控', path: '/us-monitor' },
      { id: 'us_analysis', label: '个股分析', path: '/us-analysis' },
      { id: 'us_strategies', label: '策略信号', path: '/us-strategies' },
      { id: 'us_trading', label: '模拟交易', path: '/us-trading' },
    ],
  },
];

const HK_TABS = [
  {
    group: '港股',
    items: [
      { id: 'hk_overview', label: '行情总览', path: '/hk-market' },
      { id: 'hk_monitor', label: '选股监控', path: '/hk-monitor' },
      { id: 'hk_analysis', label: '个股分析', path: '/hk-analysis' },
      { id: 'hk_strategies', label: '策略信号', path: '/hk-strategies' },
      { id: 'hk_trading', label: '模拟交易', path: '/hk-trading' },
    ],
  },
];

const MARKET_CONFIG = {
  CN_A: {
    key: 'CN_A',
    label: 'A股',
    currency: 'CNY',
    color: 'rose',
    tabs: SHARED_TABS,
  },
  HK: {
    key: 'HK',
    label: '港股',
    currency: 'HKD',
    color: 'amber',
    tabs: HK_TABS,
  },
  US: {
    key: 'US',
    label: '美股',
    currency: 'USD',
    color: 'emerald',
    tabs: US_TABS,
  },
};

const MarketContext = createContext(null);

function getInitialState() {
  // HashRouter: the hash contains the path, e.g. #/today
  const hash = window.location.hash || '';
  const path = hash.replace(/^#/, '') || '/';
  const tabId = URL_TAB_MAP[path];

  // Detect US market from URL
  if (path.startsWith('/us')) {
    return { market: 'US', tabId: tabId || 'us_overview' };
  }

  // Detect HK market from URL
  if (path.startsWith('/hk')) {
    return { market: 'HK', tabId: tabId || 'hk_overview' };
  }

  if (tabId) return { market: 'CN_A', tabId };
  return { market: 'CN_A', tabId: 'today' };
}

export function MarketProvider({ children }) {
  const initial = getInitialState();
  const [market, setMarket] = useState(initial.market);
  const [activeTabId, setActiveTabId] = useState(initial.tabId);

  const config = MARKET_CONFIG[market];

  const switchMarket = useCallback((newMarket) => {
    setMarket(newMarket);
    // 切到新市场的第一个 tab
    const firstTab = MARKET_CONFIG[newMarket]?.tabs?.[0]?.items?.[0];
    if (firstTab) {
      setActiveTabId(firstTab.id);
    }
  }, []);

  const allTabs = config?.tabs?.flatMap((g) => g.items) || [];
  const activeTab = allTabs.find((t) => t.id === activeTabId) || allTabs[0];

  return (
    <MarketContext.Provider
      value={{
        market,
        config,
        activeTabId,
        activeTab,
        switchMarket,
        setActiveTabId,
        markets: Object.keys(MARKET_CONFIG),
        getMarketConfig: (m) => MARKET_CONFIG[m],
      }}
    >
      {children}
    </MarketContext.Provider>
  );
}

export function useMarket() {
  const ctx = useContext(MarketContext);
  if (!ctx) throw new Error('useMarket must be used within MarketProvider');
  return ctx;
}

export { MARKET_CONFIG };
