import {
  Activity,
  Brain,
  CalendarDays,
  Flame,
  Gauge,
  Layers,
  Target,
  TrendingUp,
  TrendingDown,
} from 'lucide-react';
import HeaderBar from '../../components/cockpit/HeaderBar';
