const STATE_META = {
  mainline: {
    title: '主线承接',
    subtitle: '资金与情绪都在聚焦的方向',
    tone: 'text-emerald-600',
    border: 'border-emerald-500/25',
    bg: 'bg-emerald-500/8',
    icon: Flame,
  },
  watch: {
    title: '轮动观察',
    subtitle: '等待补涨确认或切换验证',
    tone: 'text-amber-600',
    border: 'border-amber-500/25',
    bg: 'bg-amber-500/8',
    icon: Target,
  },
  alive: {
    title: '尾部活口',
    subtitle: '看是否有二次发酵与承接',
    tone: 'text-rose-600',
    border: 'border-rose-500/25',
    bg: 'bg-rose-500/8',
    icon: Activity,
  },
};

function toNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function formatTextList(values, fallback = '暂无') {
  const items = Array.isArray(values)
    ? values.filter(Boolean).map((item) => String(item).trim()).filter(Boolean)
    : [];
  return items.length ? items.join(' / ') : fallback;
}

function pickBestTheme(items = []) {
  return items.reduce((best, item) => {
    const score = toNumber(item?.score ?? item?.strength ?? item?.change ?? item?.change_pct ?? 0) ?? 0;
    if (!best) {
      return { ...item, __score: score };
    }
    if (score > (best.__score ?? 0)) {
      return { ...item, __score: score };
    }
    return best;
  }, null);
}

function SectionCard({ icon: Icon, title, subtitle, children, accent = 'text-cyan-600' }) {
  return (
    <section className="rounded-[28px] border border-[var(--border-color)]/20 bg-[var(--bg-surface)] p-5 shadow-[0_0_0_1px_rgba(0,0,0,0.04)]">
      <div className="mb-4 flex items-center justify-between gap-3">
        <div>
          <div className="flex items-center gap-2 text-sm font-semibold uppercase tracking-[0.22em] text-cyan-600/75">
            {Icon ? <Icon className={`h-4 w-4 ${accent}`} /> : null}
            {title}
          </div>
          {subtitle ? <div className="mt-1 text-sm text-[var(--text-secondary)]">{subtitle}</div> : null}
        </div>
      </div>
      {children}
    </section>
  );
}

function MetricCard({ icon: Icon, label, value, hint, tone = 'text-[var(--text-primary)]', border = 'border-[var(--border-color)]/20', bg = 'bg-[var(--bg-surface)]/4' }) {
  return (
    <div className={`rounded-2xl border ${border} ${bg} p-4`}>
      <div className="flex items-center justify-between gap-3">
        <div className="text-xs font-semibold uppercase tracking-[0.18em] text-[var(--text-secondary)]">{label}</div>
        {Icon ? <Icon className="h-4 w-4 text-cyan-600/90" /> : null}
      </div>
      <div className={`mt-3 text-2xl font-bold ${tone}`}>{value}</div>
      {hint ? <div className="mt-1 text-xs leading-5 text-[var(--text-secondary)]">{hint}</div> : null}
    </div>
  );
}

function LifecycleCard({ state, items }) {
  const meta = STATE_META[state];
  const Icon = meta.icon;
  const best = pickBestTheme(items);
  const topNames = (items || []).slice(0, 3).map((item) => item?.name).filter(Boolean);
  const reasons = Array.isArray(best?.reasons) ? best.reasons.slice(0, 3) : [];

  return (
    <div className={`rounded-[24px] border ${meta.border} ${meta.bg} p-4`}>
      <div className="flex items-start justify-between gap-3">
        <div>
          <div className={`flex items-center gap-2 text-sm font-semibold ${meta.tone}`}>
            <Icon className="h-4 w-4" />
            {meta.title}
          </div>
          <div className="mt-1 text-xs text-[var(--text-secondary)]">{meta.subtitle}</div>
        </div>
        <div className="rounded-full border border-[var(--border-color)]/20 bg-[var(--bg-surface)]/5 px-2.5 py-1 text-[11px] font-semibold text-[var(--text-secondary)]">
          {items.length} 个
        </div>
      </div>

      <div className="mt-4 space-y-3">
        <div className="rounded-2xl border border-[var(--border-color)]/20 bg-[var(--bg-surface)] px-3 py-3">
          <div className="text-[11px] uppercase tracking-[0.16em] text-[var(--text-secondary)]">当前最强</div>
          <div className="mt-1 text-base font-semibold text-[var(--text-primary)]">{best?.name || '暂无数据'}</div>
          <div className="mt-1 text-xs text-[var(--text-secondary)]">龙头：{best?.leader || '暂无'}</div>
          <div className="mt-2 text-sm text-[var(--text-secondary)]">{best?.judgment || best?.note || '题材仍在观察中。'}</div>
        </div>

        <div className="rounded-2xl border border-[var(--border-color)]/20 bg-[var(--bg-surface)] px-3 py-3">
          <div className="text-[11px] uppercase tracking-[0.16em] text-[var(--text-secondary)]">题材强弱</div>
          <div className="mt-2 h-2 rounded-full bg-[var(--bg-card)]/8">
            <div
              className="h-2 rounded-full bg-gradient-to-r from-cyan-400 to-blue-500"
              style={{ width: `${Math.max(10, Math.min(100, toNumber(best?.score ?? best?.strength ?? 0) ?? 0))}%` }}
            />
          </div>
          <div className="mt-2 flex items-center justify-between text-xs text-[var(--text-secondary)]">
            <span>题材条目</span>
            <span>重点看 {topNames.join(' / ') || '暂无'}</span>
          </div>
        </div>

        {reasons.length ? (
          <div className="flex flex-wrap gap-2">
            {reasons.map((reason, index) => (
              <span key={`${state}-reason-${index}`} className="rounded-full border border-[var(--border-color)]/20 bg-[var(--bg-surface)]/5 px-2.5 py-1 text-[11px] text-[var(--text-primary)]">
                {reason}
              </span>
            ))}
          </div>
        ) : null}
      </div>
    </div>
  );
}

function AIInsightPanel({ review, mainHub, liveContext }) {
  const cognition = review?.cognition || {};
  const summaryText = review?.summary?.text || review?.rotation_report?.summary || '';
  const stageDescription = cognition?.stage_description || mainHub?.stage_description || '';
  const rotationConclusion =
    review?.rotation?.comparison?.conclusion ||
    mainHub?.rotation?.comparison?.conclusion ||
    '';
  const themeSignals = [
    ...(cognition?.signals?.theme || []),
    ...(review?.rotation?.signals?.theme || []),
  ].filter(Boolean);
  const riskSignals = [
    ...(cognition?.warnings || []),
    ...(review?.risk_warning || []),
  ].filter(Boolean);
  const nextAttack = (review?.tomorrow_plan?.attack || []).slice(0, 3);
  const nextDefense = (review?.tomorrow_plan?.defense || []).slice(0, 3);
  const mainlineNames = formatTextList((review?.themes?.mainline || []).map((item) => item?.name), '暂无明显主线');
  const liveStage = liveContext?.stage || mainHub?.stage || cognition?.stage || '';
  const liveRisk = liveContext?.risk_level || mainHub?.risk_level || cognition?.risk_level || '';

  const bulletRows = useMemo(() => {
    const rows = [];
    if (summaryText) rows.push(`策略结论：${summaryText}`);
    if (stageDescription) rows.push(`阶段解释：${stageDescription}`);
    if (rotationConclusion) rows.push(`轮动判断：${rotationConclusion}`);
    if (themeSignals.length) rows.push(`题材信号：${themeSignals.slice(0, 4).join(' / ')}`);
    if (riskSignals.length) rows.push(`风险提示：${riskSignals.slice(0, 3).join('；')}`);
    if (nextAttack.length) rows.push(`进攻方向：${nextAttack.join('；')}`);
    if (nextDefense.length) rows.push(`防守提示：${nextDefense.join('；')}`);
    if (liveStage || liveRisk) rows.push(`实时状态：${liveStage || '未识别'} / 风险 ${liveRisk || '未知'}`);
    rows.push(`主线追踪：${mainlineNames}`);
    return rows;
  }, [
    liveRisk,
    liveStage,
    mainlineNames,
    nextAttack,
    nextDefense,
    rotationConclusion,
    riskSignals,
    stageDescription,
    summaryText,
    themeSignals,
  ]);

  return (
    <SectionCard
      icon={Brain}
      title="AI 综合分析"
      subtitle="AI 只做策略结果的归纳、对照和提醒，不替代主线判断。"
      accent="text-cyan-600"
    >
      <div className="grid gap-3 lg:grid-cols-[1.2fr_0.8fr]">
        <div className="rounded-[24px] border border-cyan-200/40 bg-cyan-500/5 p-4">
          <div className="text-sm font-semibold text-cyan-700">综合结论</div>
          <div className="mt-3 space-y-2">
            {bulletRows.map((row, index) => (
              <div key={`ai-bullet-${index}`} className="rounded-2xl border border-[var(--border-color)]/20 bg-[var(--bg-surface)] px-3 py-2 text-sm leading-6 text-[var(--text-primary)]">
                {row}
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-3">
          <div className="rounded-[24px] border border-[var(--border-color)]/20 bg-[var(--bg-surface)] p-4">
            <div className="text-xs font-semibold uppercase tracking-[0.18em] text-[var(--text-secondary)]">今日关键词</div>
            <div className="mt-3 flex flex-wrap gap-2">
              {(themeSignals.slice(0, 4).concat(riskSignals.slice(0, 2)) || []).length ? (
                themeSignals.slice(0, 4).concat(riskSignals.slice(0, 2)).map((item, index) => (
                  <span key={`keyword-${index}`} className="rounded-full border border-[var(--border-color)]/20 bg-[var(--bg-surface)]/5 px-3 py-1 text-[11px] text-[var(--text-primary)]">
                    {item}
                  </span>
                ))
              ) : (
                <span className="text-sm text-[var(--text-secondary)]">暂无关键词</span>
              )}
            </div>
          </div>

          <div className="rounded-[24px] border border-[var(--border-color)]/20 bg-[var(--bg-surface)] p-4">
            <div className="text-xs font-semibold uppercase tracking-[0.18em] text-[var(--text-secondary)]">题材结论</div>
            <div className="mt-2 text-sm leading-6 text-[var(--text-secondary)]">
              {summaryText || '策略侧还没有足够明确的文字结论，当前更适合看主线结构和资金承接。'}
            </div>
          </div>
        </div>
      </div>
    </SectionCard>
  );
}

function ActionPlanPanel({ plan }) {
  const attack = Array.isArray(plan?.attack) ? plan.attack : [];
  const secondary = Array.isArray(plan?.secondary) ? plan.secondary : [];
  const defense = Array.isArray(plan?.defense) ? plan.defense : [];

  const renderList = (items, emptyText) => {
    if (!items.length) {
      return <div className="text-sm text-[var(--text-secondary)]">{emptyText}</div>;
    }
    return (
      <div className="space-y-2">
        {items.map((item, index) => (
          <div key={`${emptyText}-${index}`} className="rounded-2xl border border-[var(--border-color)]/20 bg-[var(--bg-surface)] px-3 py-2 text-sm text-[var(--text-primary)]">
            {item}
          </div>
        ))}
      </div>
    );
  };

  return (
    <SectionCard icon={Gauge} title="次日行动建议" subtitle="把复盘结果落成明天可执行的动作。">
      <div className="grid gap-3 lg:grid-cols-3">
        <div className="rounded-[24px] border border-emerald-500/20 bg-emerald-500/5 p-4">
          <div className="flex items-center gap-2 text-sm font-semibold text-emerald-600">
            <TrendingUp className="h-4 w-4" />
            进攻方向
          </div>
          <div className="mt-3">{renderList(attack, '暂无进攻方向')}</div>
        </div>
        <div className="rounded-[24px] border border-amber-500/20 bg-amber-500/5 p-4">
          <div className="flex items-center gap-2 text-sm font-semibold text-amber-600">
            <Activity className="h-4 w-4" />
            观察方向
          </div>
          <div className="mt-3">{renderList(secondary, '暂无观察方向')}</div>
        </div>
        <div className="rounded-[24px] border border-rose-500/20 bg-rose-500/5 p-4">
          <div className="flex items-center gap-2 text-sm font-semibold text-rose-600">
            <TrendingDown className="h-4 w-4" />
            防守方向
          </div>
          <div className="mt-3">{renderList(defense, '暂无防守方向')}</div>
        </div>
      </div>
    </SectionCard>
  );
}

export default function ThemeTrackPage({ shellMode, market = 'CN_A' } = {}) {
  const {
    review,
    loading: reviewLoading,
    refreshing: reviewRefreshing,
    selectedDate,
    setSelectedDate,
    syncReview,
    updatedAt: reviewUpdatedAt,
    mainHub: reviewMainHub,
  } = useMarketReviewData({ market });
  const {
    context: liveContext,
    loading: liveLoading,
    refreshing: liveRefreshing,
    syncContext,
    updatedAt: liveUpdatedAt,
  } = useMainHubContext({ market });

  const [themes, setThemes] = useState([]);
  const [themeDate, setThemeDate] = useState('');
  const [themeLoading, setThemeLoading] = useState(true);
  const [themeRefreshing, setThemeRefreshing] = useState(false);
  const [themeUpdatedAt, setThemeUpdatedAt] = useState('');
  const [themeError, setThemeError] = useState('');

  const fetchThemes = useCallback(async ({ silent = false } = {}) => {
    if (!silent) {
      setThemeLoading(true);
      setThemeError('');
    } else {
      setThemeRefreshing(true);
    }

    try {
      const response = await fetch(marketApiUrl('concept-themes', market));
      const data = await response.json();
      if (data.ok) {
        setThemes(Array.isArray(data.themes) ? data.themes : []);
        setThemeDate(data.date || '');
        setThemeUpdatedAt(new Date().toLocaleString('zh-CN'));
      } else {
        throw new Error(data.detail || data.error || '获取题材数据失败');
      }
    } catch (errorValue) {
      setThemeError(errorValue?.message || '无法获取题材数据');
    } finally {
      setThemeLoading(false);
      setThemeRefreshing(false);
    }
  }, [market]);

  useEffect(() => {
    fetchThemes();
  }, [fetchThemes]);

  useEffect(() => {
    const timer = window.setInterval(() => {
      fetchThemes({ silent: true });
    }, 60000);

    return () => window.clearInterval(timer);
  }, [fetchThemes]);

  const refreshAll = useCallback(() => {
    syncReview({ silent: true });
    syncContext({ silent: true });
    fetchThemes({ silent: true });
  }, [fetchThemes, syncContext, syncReview]);

  const combinedLoading = reviewLoading || liveLoading || themeLoading;
  const combinedRefreshing = reviewRefreshing || liveRefreshing || themeRefreshing;
  const updatedAt = themeUpdatedAt || reviewUpdatedAt || liveUpdatedAt || '';

  const groups = useMemo(() => {
    return (themes || []).reduce(
      (acc, item) => {
        const state = item?.state || 'watch';
        if (!acc[state]) {
          acc[state] = [];
        }
        acc[state].push(item);
        return acc;
      },
      { mainline: [], watch: [], alive: [] },
    );
  }, [themes]);

  const mainlineThemes = groups.mainline || [];
  const watchThemes = groups.watch || [];
  const aliveThemes = groups.alive || [];

  const liveHub = liveContext || reviewMainHub?.market_context || {};
  const dispatch = reviewMainHub?.dispatch || {};
  const cognition = review.cognition || reviewMainHub?.cognition || {
    stage: '',
    risk_level: '',
    position: '',
    signals: { stage: [], theme: [], risk: [] },
    warnings: [],
  };

  const stageValue = liveHub.stage || cognition.stage || dispatch.market_stage || '';
  const riskValue = liveHub.risk_level || cognition.risk_level || dispatch.risk_level || '';
  const positionValue = liveHub.position_suggestion || dispatch.position_suggestion || review.tomorrow_plan?.position || '';
  const themeCount = themes.length;
  const themeSource = themeDate || review.date || selectedDate || '';
  const reviewStatus = review.status === 'missing' ? '缺失' : (review.status || '缺失');
  const mainlineNames = formatTextList(mainlineThemes.slice(0, 3).map((item) => item?.name), '暂无主线');
  const watchNames = formatTextList(watchThemes.slice(0, 3).map((item) => item?.name), '暂无观察');
  const aliveNames = formatTextList(aliveThemes.slice(0, 3).map((item) => item?.name), '暂无活口');

  const contentBlock = (
    <>
      <div className="rounded-[24px] border border-cyan-200/40 bg-cyan-500/8 px-4 py-3">
        <div className="flex flex-wrap items-center gap-2 text-sm text-cyan-700/90">
          <span className="rounded-full border border-cyan-300/40 bg-cyan-50 px-3 py-1 text-xs font-semibold text-cyan-700">
            策略先行
          </span>
          <span className="rounded-full border border-[var(--border-color)]/20 bg-[var(--bg-surface)]/4 px-3 py-1 text-xs text-[var(--text-primary)]">
            题材源 {themeSource || '--'}
          </span>
          <span className="rounded-full border border-[var(--border-color)]/20 bg-[var(--bg-surface)]/4 px-3 py-1 text-xs text-[var(--text-primary)]">
            复盘状态 {reviewStatus}
          </span>
        </div>
        <div className="mt-2 text-xs leading-5 text-[var(--text-secondary)]">
          这页的顺序已经重组为：策略结论先出，AI 做综合分析，再看题材战场、资金联动和次日动作。
        </div>
      </div>

      <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-6">
        <MetricCard
          icon={CalendarDays}
          label="题材日期"
          value={themeSource || '--'}
          hint="题材复盘对应的交易日"
        />
        <MetricCard
          icon={Layers}
          label="题材数量"
          value={themeCount}
          hint="主线 / 观察 / 活口合计"
        />
        <MetricCard
          icon={Flame}
          label="主线"
          value={mainlineThemes.length}
          hint={mainlineNames}
          tone="text-emerald-600"
          border="border-emerald-500/25"
          bg="bg-emerald-500/6"
        />
        <MetricCard
          icon={Target}
          label="观察"
          value={watchThemes.length}
          hint={watchNames}
          tone="text-amber-600"
          border="border-amber-500/25"
          bg="bg-amber-500/6"
        />
        <MetricCard
          icon={Activity}
          label="活口"
          value={aliveThemes.length}
          hint={aliveNames}
          tone="text-rose-600"
          border="border-rose-500/25"
          bg="bg-rose-500/6"
        />
        <MetricCard
          icon={Gauge}
          label="市场判断"
          value={stageValue || '未识别'}
          hint={`风险 ${riskValue || '未知'} / 仓位 ${positionValue || '-'}`}
          tone="text-cyan-600"
          border="border-cyan-400/20"
          bg="bg-cyan-500/5"
        />
      </div>

      {themeError ? (
        <div className="rounded-3xl border border-rose-400/30 bg-rose-50 px-5 py-4 text-rose-700">
          {themeError}
        </div>
      ) : null}

      <SectionCard
        icon={Layers}
        title="题材战场"
        subtitle="主线、观察、活口三栏直接承接策略结果。"
        accent="text-cyan-600"
      >
        <ThemeBattlefield
          themes={{
            mainline: mainlineThemes,
            watch: watchThemes,
            alive: aliveThemes,
          }}
          cognition={cognition}
          loading={combinedLoading && !themes.length}
        />
      </SectionCard>

      <SectionCard
        icon={Flame}
        title="题材生命周期"
        subtitle="把题材放到承接、轮动、活口三个阶段里看，方便你判断是延续还是切换。"
        accent="text-amber-600"
      >
        <div className="grid gap-3 xl:grid-cols-3">
          <LifecycleCard state="mainline" items={mainlineThemes} />
          <LifecycleCard state="watch" items={watchThemes} />
          <LifecycleCard state="alive" items={aliveThemes} />
        </div>
      </SectionCard>

      <AIInsightPanel review={review} mainHub={reviewMainHub?.market_context} liveContext={liveHub} />

      <SectionCard
        icon={TrendingUp}
        title="资金流向"
        subtitle="题材判断要和资金承接一起看，不然容易只看热度不看结果。"
        accent="text-emerald-600"
      >
        <FundFlowPanel
          data={review.fund_flow}
          themes={review.themes}
          loading={reviewLoading}
        />
      </SectionCard>

      <ActionPlanPanel plan={review.tomorrow_plan} />
    </>
  );

  if (shellMode) {
    return (
      <div className="space-y-3">
        {contentBlock}
      </div>
    );
  }

  return (
    <div className="min-h-screen text-[var(--text-primary)]">
      <div className="mx-auto flex min-h-screen max-w-[1440px]">
        <CockpitSidebar
          collapsed={false}
          onToggleCollapsed={() => {}}
          activeNav="theme_track"
          updatedAt={updatedAt || themeUpdatedAt || reviewUpdatedAt || liveUpdatedAt}
          status="题材"
          onNavigateItem={() => {}}
        />

        <main className="flex-1 overflow-y-auto scrollbar-thin">
          <div className="mx-auto w-full max-w-[1440px] px-3 py-3 lg:px-4">
            <HeaderBar
              date={selectedDate}
              onDateChange={setSelectedDate}
              updatedAt={updatedAt || themeUpdatedAt || reviewUpdatedAt || liveUpdatedAt}
              dataStatus={reviewStatus}
              resolvedDate={review.date || themeDate || selectedDate}
              viewMode="HISTORY"
              cognition={cognition}
              onExportPdf={() => window.print()}
              onRefresh={refreshAll}
              refreshing={combinedRefreshing}
              titleOverride="题材复盘 · 策略优先"
              phaseTagOverride="盘后题材"
            />

            <div className="mt-3 space-y-3">
              {contentBlock}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
