import { useEffect, useRef, useState } from 'react';
import { marketApiUrl, isCNA } from '../lib/marketApi';

export function useMockPosition({ market = 'CN_A' } = {}) {
  const [position, setPosition] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [updatedAt, setUpdatedAt] = useState('');
  const requestControllerRef = useRef(null);

  const apiUrl = isCNA(market)
    ? '/api/mock-trading/positions?force_refresh=true'
    : marketApiUrl('positions', market);

  const syncPosition = async ({ silent = false } = {}) => {
    if (requestControllerRef.current) {
      requestControllerRef.current.abort();
    }
    const controller = new AbortController();
    requestControllerRef.current = controller;

    try {
      if (!silent) {
        setLoading(true);
        setError('');
      } else {
        setRefreshing(true);
      }

      const response = await fetch(apiUrl, {
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      if (controller.signal.aborted) return;

      if (data.posList || data.totalAssets) {
        setPosition(data);
        // 优先使用API返回的更新时间，兼容后端不同字段名
        setUpdatedAt(data.updatedAt || data.updated_at || new Date().toLocaleString());
      } else {
        throw new Error(data.message || '获取持仓失败');
      }
    } catch (err) {
      if (err?.name === 'AbortError') {
        return;
      }
      setError(err.message || '无法获取模拟盘持仓数据');
    } finally {
      if (requestControllerRef.current === controller) {
        requestControllerRef.current = null;
      }
      if (!controller.signal.aborted) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  };

  useEffect(() => {
    syncPosition();
    return () => {
      if (requestControllerRef.current) {
        requestControllerRef.current.abort();
      }
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [market]);

  // 自动刷新：每 5 分钟更新
  useEffect(() => {
    const interval = setInterval(() => {
      syncPosition({ silent: true });
    }, 5 * 60 * 1000); // 5分钟

    return () => clearInterval(interval);
  }, []);

  return {
    position,
    loading,
    refreshing,
    error,
    updatedAt,
    syncPosition,
  };
}
