import { ThemeProvider } from '../hermes-today/contexts/ThemeContext';
import { MarketProvider } from '../hermes-today/contexts/MarketContext';

// Hermes 子系统模块已原生迁移到 AIROBOT（不再用 iframe）。
// 这里统一用 hermes-today 中的原生组件渲染，并由 AIROBOT 主布局承载导航。
import MarketToday from '../hermes-today/pages/MarketToday';
import MainHub from '../hermes-today/pages/MainHub';
import ThemeTrackPage from '../hermes-today/pages/modules/ThemeTrackPage';
import EmotionHubPage from '../hermes-today/pages/modules/EmotionHubPage';
import StockMonitorPage from '../hermes-today/pages/modules/StockMonitorPage';
import RobotStrategiesPage from '../hermes-today/pages/RobotStrategiesPage';
import StrategyPositionPage from '../hermes-today/pages/modules/StrategyPositionPage';
import MockTradingPage from '../hermes-today/pages/MockTradingPage';

// module -> 组件 + 默认 props
const MODULE_MAP = {
  // 盘中实时
  today: { Component: MarketToday, props: { shellMode: true, market: 'CN_A' } },

  // 数据中心（共用 MainHub，activeTabId 决定市场/视图）
  dc_overview: { Component: MainHub, props: { shellMode: true, activeTabId: 'data_center' } },
  dc_a_share: { Component: MainHub, props: { shellMode: true, activeTabId: 'dc_market' } },
  dc_hk: { Component: MainHub, props: { shellMode: true, activeTabId: 'dc_sector' } },
  dc_us: { Component: MainHub, props: { shellMode: true, activeTabId: 'dc_moneyflow' } },
  dc_schedule: { Component: MainHub, props: { shellMode: true, activeTabId: 'data_center' } },

  // 题材复盘 / 综合数据
  theme_review: { Component: ThemeTrackPage, props: { shellMode: true } },
  consolidated: { Component: EmotionHubPage, props: {} },

  // 选股持仓 / 策略信号 / 波段信号 / 模拟交易
  stock_monitor: { Component: StockMonitorPage, props: { embedded: true } },
  strategies: { Component: RobotStrategiesPage, props: {} },
  strategy_position: { Component: StrategyPositionPage, props: {} },
  mock_trading: { Component: MockTradingPage, props: { embedded: true, shellMode: true } },
};

export default function HermesModulePage({ module }) {
  const m = MODULE_MAP[module];
  if (!m) {
    return (
      <div className="p-8 text-sm text-[var(--text-muted)]">
        未知模块：{module}
      </div>
    );
  }
  const { Component, props } = m;
  return (
    <ThemeProvider>
      <MarketProvider>
        <Component {...props} />
      </MarketProvider>
    </ThemeProvider>
  );
}
