/**
 * 外部数据平台股票链接生成器
 * 支持新浪、东方财富、同花顺、腾讯财经
 */

function normalizeCode(code) {
  if (!code) return '';
  let c = String(code).trim().toUpperCase();
  // 去掉前缀 SH/SZ/BJ
  c = c.replace(/^(SH|SZ|BJ|HK|US)/, '');
  // 去掉后缀 .SH/.SZ/.BJ
  c = c.replace(/\.(SH|SZ|BJ|HK|US)$/, '');
  return c;
}

function detectExchange(code) {
  const c = normalizeCode(code);
  if (!c) return 'SH';
  // 6xx/9xx -> SH, 0xx/3xx -> SZ
  if (c.startsWith('6') || c.startsWith('9')) return 'SH';
  return 'SZ';
}

function tsCode(code) {
  const c = normalizeCode(code);
  if (!c) return '';
  return `${c}.${detectExchange(code)}`;
}

function eastMoneyCode(code) {
  const c = normalizeCode(code);
  if (!c) return '';
  const exch = detectExchange(code);
  // 东方财富: 1=上海, 0=深圳
  return exch === 'SH' ? `1.${c}` : `0.${c}`;
}

/** 新浪财经 */
export function getSinaUrl(code) {
  const c = normalizeCode(code);
  if (!c) return null;
  return `https://finance.sina.com.cn/realstock/company/${detectExchange(code)}${c}/nc.shtml`;
}

/** 东方财富 */
export function getEastMoneyUrl(code) {
  const c = normalizeCode(code);
  if (!c) return null;
  return `https://quote.eastmoney.com/${detectExchange(code).toLowerCase()}${c}.html`;
}

/** 同花顺 */
export function getTHSUrl(code) {
  const c = normalizeCode(code);
  if (!c) return null;
  return `https://stockpage.10jqka.com.cn/${c}/`;
}

/** 腾讯财经 */
export function getTencentUrl(code) {
  const c = normalizeCode(code);
  if (!c) return null;
  const exch = detectExchange(code);
  return `https://gu.qq.com/${exch}${c}`;
}

/** 统一返回{ sina, eastmoney, ths, tencent } */
export function getAllUrls(code) {
  return {
    sina: getSinaUrl(code),
    eastmoney: getEastMoneyUrl(code),
    ths: getTHSUrl(code),
    tencent: getTencentUrl(code),
  };
}

export { normalizeCode, detectExchange, tsCode, eastMoneyCode };
