import React from 'react';
import { Compass, Calendar, BookOpen } from 'lucide-react';
import { useMarketReviewData } from '../../hooks/useMarketReviewData';
import HeaderBar from '../../components/cockpit/HeaderBar';
import CockpitSidebar from '../../components/cockpit/CockpitSidebar';
import EmotionGauge from '../../components/cockpit/EmotionGauge';
import { DataCard, EmptyBlock } from './ModuleCommon';
import { useState } from 'react';

export default function EmotionHubPage() {
  const {
    review,
    loading,
    selectedDate,
    setSelectedDate,
    updatedAt,
    refreshing,
    syncReview,
    viewMode,
    cognition
  } = useMarketReviewData();
  // collapsed removed

  const calendarBlock = review?.calendar || {};
  const calendarEvents = calendarBlock?.data || [];
  const researchBlock = review?.research || {};
  const researchItems = researchBlock?.data || [];

  return (
    <div className="min-h-screen text-[var(--text-primary)]">
      <div className="mx-auto flex min-h-screen max-w-[1440px]">
        <CockpitSidebar
          collapsed={false}
          onToggleCollapsed={() => {}}
          activeNav="nav-emotion"
          updatedAt={updatedAt || review?.meta?.updated_at}
          status={review?.meta?.status}
          onNavigateItem={() => {}}
        />
        <main className="flex-1 overflow-y-auto scrollbar-thin">
          <div className="mx-auto w-full max-w-[1440px] px-3 py-3 lg:px-4">
            <HeaderBar
              date={selectedDate}
              onDateChange={setSelectedDate}
              updatedAt={updatedAt || review?.meta?.updated_at}
              dataStatus={review?.meta?.status}
              viewMode={viewMode}
              cognition={cognition}
              onRefresh={() => syncReview({ silent: true })}
              refreshing={refreshing}
              titleOverride={`${selectedDate} · 市场情绪与宏观风向`}
              phaseTagOverride="二级页面"
            />
            <div className="mt-3 space-y-3">
              <div className="flex flex-col gap-1 border-b border-[var(--border-color)] pb-3">
                <h1 className="text-xl font-bold tracking-tight text-[var(--text-primary)] flex items-center gap-2">
                  <Compass className="h-5 w-5 text-amber-600" />
                  市场情绪雷达与宏观风向标
                </h1>
                <p className="text-xs text-[var(--text-secondary)] font-mono">MARKET_EMOTION_AND_RESEARCH_MACRO</p>
              </div>

              {loading ? (
                <div className="p-4 text-[var(--text-secondary)] font-mono text-xs animate-pulse">LOADING_EMOTION_MATRIX...</div>
              ) : (
                <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
                  <div className="lg:col-span-1">
                    <EmotionGauge emotion={review?.emotion} loading={loading} />
                  </div>

                  <div className="lg:col-span-1">
                    <DataCard title="重要交易日历 / 备忘" icon={Calendar}>
                      {!calendarEvents.length ? (
                        <EmptyBlock message="当前交易日无重大宏观/节点事件" />
                      ) : (
                        <div className="space-y-2 max-h-[360px] overflow-y-auto pr-1">
                          {calendarEvents.map((ev, idx) => (
                            <div key={idx} className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-surface)]/30 p-2.5 font-mono text-xs">
                              <div className="text-amber-600 font-bold mb-1">{ev.time || '盘前/盘后'}</div>
                              <div className="text-[var(--text-primary)] font-sans">{ev.event || ev.content || '--'}</div>
                            </div>
                          ))}
                        </div>
                      )}
                    </DataCard>
                  </div>

                  <div className="lg:col-span-1">
                    <DataCard title="首席投研与精选纪要" icon={BookOpen}>
                      {!researchItems.length ? (
                        <EmptyBlock message="暂无新增深度策略研报" />
                      ) : (
                        <div className="space-y-2 max-h-[360px] overflow-y-auto pr-1">
                          {researchItems.map((item, idx) => (
                            <div key={idx} className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] p-2.5">
                              <div className="text-xs font-bold text-[var(--text-primary)] truncate">{item.title || '未命名研报'}</div>
                              <p className="mt-1 text-[11px] text-[var(--text-secondary)] line-clamp-2 font-sans">{item.summary || item.content}</p>
                              <div className="mt-1.5 flex justify-between items-center text-[10px] font-mono text-[var(--text-secondary)]">
                                <span>{item.source || 'Hermes核心'}</span>
                                <span>{item.date || '--'}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </DataCard>
                  </div>
                </div>
              )}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
