/**
 * 生命周期 StageBar — 7 段式股票阶段可视化
 * 跟随 → 关注 → 吸筹 → 启动 → 发酵 → 主升 → 退潮
 */
const STAGES = ['跟随', '关注', '吸筹', '启动', '发酵', '主升', '退潮'];

const STAGE_COLORS = {
  '跟随': '#94a3b8',
  '关注': '#a855f7',
  '吸筹': '#06b6d4',
  '启动': '#eab308',
  '发酵': '#f97316',
  '主升': '#ef4444',
  '退潮': '#6b7280',
};

export function inferStage(profitPct) {
  const p = Number(profitPct) || 0;
  if (p >= 50) return '主升';
  if (p >= 20) return '发酵';
  if (p >= 10) return '启动';
  if (p >= 1) return '吸筹';
  if (p >= -2) return '关注';
  if (p >= -8) return '跟随';
  return '退潮';
}

export default function StageBar({ profitPct, size = 'sm' }) {
  const stage = inferStage(profitPct);
  const idx = STAGES.indexOf(stage);

  return (
    <div className="flex items-center gap-0.5 w-full">
      {STAGES.map((s, i) => {
        const filled = i <= idx;
        const color = STAGE_COLORS[s];
        return (
          <div
            key={s}
            title={`${s}${filled ? ` (当前: ${stage})` : ''}`}
            className={`flex-1 h-1 rounded-sm transition-colors duration-300 ${
              size === 'md' ? 'h-1.5' : ''
            }`}
            style={{
              backgroundColor: filled ? color : 'var(--border-color)',
              opacity: filled ? (i === idx ? 1 : 0.7) : 0.3,
            }}
          />
        );
      })}
      <span
        className="ml-1 text-[10px] font-medium whitespace-nowrap"
        style={{ color: STAGE_COLORS[stage] || '#94a3b8' }}
      >
        {stage}
      </span>
    </div>
  );
}

export { STAGES, STAGE_COLORS };
