import { useCallback, useEffect, useState } from 'react';
import { DEFAULT_CUSTOM_STRATEGY_KEYS, ROBOT_REGISTRY } from '../lib/robotRegistry';

function resolveFallbackMarket(robotId) {
  const numericId = Number(String(robotId || '').split('-')[1] || 0);
  if (numericId >= 19 && numericId <= 20) return '港股';
  if (numericId >= 21 && numericId <= 25) return '美股';
  return 'A股';
}

const FALLBACK_CATALOG = ROBOT_REGISTRY.map((robot) => ({
  id: robot.id,
  key: robot.key,
  name: robot.name,
  displayName: robot.displayName || robot.name,
  emoji: robot.emoji,
  color: robot.color,
  desc: robot.desc,
  market: resolveFallbackMarket(robot.id),
  data_key: 'stocks',
  default_custom: DEFAULT_CUSTOM_STRATEGY_KEYS.includes(robot.key),
  runnable: true,
}));

function normalizeCatalogItem(item) {
  if (!item || typeof item !== 'object') return null;
  const id = String(item.id || item.robot_id || item.robotId || '').trim();
  const key = String(item.key || item.strategy_key || item.strategyKey || '').trim();
  if (!id || !key) return null;
  return {
    id,
    key,
    name: String(item.name || item.label || id || key),
    displayName: String(item.display_name || item.displayName || item.name || item.label || id || key),
    emoji: String(item.emoji || ''),
    color: String(item.color || 'slate'),
    desc: String(item.desc || item.description || ''),
    market: String(item.market || item.region || ''),
    data_key: String(item.data_key || item.dataKey || 'stocks'),
    default_custom: Boolean(item.default_custom ?? item.defaultCustom ?? false),
    runnable: Boolean(item.runnable ?? item.has_script ?? false),
    raw: item,
  };
}

function normalizeCatalogResponse(payload) {
  const root = payload && typeof payload === 'object' ? payload : {};
  const items = Array.isArray(root)
    ? root
    : Array.isArray(root.items)
      ? root.items
      : Array.isArray(root.data)
        ? root.data
        : [];
  const normalizedItems = items.map(normalizeCatalogItem).filter(Boolean);
  const defaultCustomStrategyKeys = Array.isArray(root.default_custom_strategy_keys)
    ? root.default_custom_strategy_keys.filter(Boolean)
    : Array.isArray(root.defaultCustomStrategyKeys)
      ? root.defaultCustomStrategyKeys.filter(Boolean)
      : DEFAULT_CUSTOM_STRATEGY_KEYS;
  const robotIds = Array.isArray(root.robot_ids)
    ? root.robot_ids.filter(Boolean)
    : normalizedItems.map((item) => item.id);

  return {
    items: normalizedItems,
    defaultCustomStrategyKeys,
    robotIds,
  };
}

export function useStrategyCatalog() {
  const [catalog, setCatalog] = useState(FALLBACK_CATALOG);
  const [strategyOptions, setStrategyOptions] = useState(
    FALLBACK_CATALOG.map((item) => ({
      value: item.key,
      label: `${item.emoji ? `${item.emoji} ` : ''}${item.name}`,
    }))
  );
  const [defaultCustomStrategyKeys, setDefaultCustomStrategyKeys] = useState(DEFAULT_CUSTOM_STRATEGY_KEYS);
  const [robotIds, setRobotIds] = useState(FALLBACK_CATALOG.map((item) => item.id));
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/ops/strategy-catalog');
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }
      const data = await response.json();
      const normalized = normalizeCatalogResponse(data);
      const nextCatalog = normalized.items.length > 0 ? normalized.items : FALLBACK_CATALOG;
      setCatalog(nextCatalog);
      setStrategyOptions(
        nextCatalog.map((item) => ({
          value: item.key,
          label: `${item.emoji ? `${item.emoji} ` : ''}${item.name}`,
        }))
      );
      setDefaultCustomStrategyKeys(
        normalized.defaultCustomStrategyKeys.length > 0
          ? normalized.defaultCustomStrategyKeys
          : DEFAULT_CUSTOM_STRATEGY_KEYS
      );
      setRobotIds(normalized.robotIds.length > 0 ? normalized.robotIds : nextCatalog.map((item) => item.id));
      setError('');
    } catch (err) {
      console.error('Failed to fetch strategy catalog:', err);
      setCatalog((prev) => (prev.length > 0 ? prev : FALLBACK_CATALOG));
      setStrategyOptions(
        FALLBACK_CATALOG.map((item) => ({
          value: item.key,
          label: `${item.emoji ? `${item.emoji} ` : ''}${item.name}`,
        }))
      );
      setDefaultCustomStrategyKeys(DEFAULT_CUSTOM_STRATEGY_KEYS);
      setRobotIds(FALLBACK_CATALOG.map((item) => item.id));
      setError('无法获取策略目录');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  return {
    catalog,
    strategyOptions,
    defaultCustomStrategyKeys,
    robotIds,
    loading,
    error,
    refresh,
  };
}
