import { useEffect, useState } from 'react';
import { ROBOT_IDS } from '../lib/robotRegistry';

export function useBacktestData() {
  const [backtestData, setBacktestData] = useState({});
  const [loading, setLoading] = useState(true);

  const fetchBacktestData = async () => {
    try {
      const results = {};
      for (const robotId of ROBOT_IDS) {
        try {
          const res = await fetch(`/api/ops/backtest/${robotId}`);
          if (res.ok) {
            const data = await res.json();
            if (data.data) {
              results[robotId] = data;
            }
          }
        } catch (e) {
          // Robot might not have backtest data yet
        }
      }
      setBacktestData(results);
    } catch (err) {
      console.error('Failed to fetch backtest data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBacktestData();
    // 每30秒刷新
    const interval = setInterval(fetchBacktestData, 30000);
    return () => clearInterval(interval);
  }, []);

  return {
    backtestData,
    loading,
    refresh: fetchBacktestData,
  };
}
