import React from 'react';

export function StatusPill({ block }) {
  const status = block?.status || 'missing';
  const source = block?.source || 'unknown';
  const updatedAt = block?.updated_at || '--';
  const tone = status === 'latest'
    ? 'text-emerald-400 border-emerald-500/20 bg-emerald-500/5'
    : status === 'delayed'
      ? 'text-amber-600 border-amber-500/20 bg-amber-500/5'
      : 'text-rose-400 border-rose-500/20 bg-rose-500/5';

  return (
    <div className="mb-4 flex flex-wrap items-center gap-2 text-[10px] font-mono font-bold tracking-wide">
      <span className={`rounded border px-2 py-0.5 tracking-widest uppercase ${tone}`}>{status}</span>
      <span className="rounded border border-[var(--border-color)] bg-[var(--bg-surface)]/60 px-2 py-0.5 text-[var(--text-secondary)]">SRC: {source}</span>
      <span className="rounded border border-[var(--border-color)] bg-[var(--bg-surface)]/60 px-2 py-0.5 text-[var(--text-secondary)]">SYNC: {updatedAt ? String(updatedAt).replace('T', ' ').replace(/Z$/, '').replace(/(\d{4})-(\d{2})-(\d{2})/, '$1/$2/$3') : ''}</span>
    </div>
  );
}

export function EmptyBlock({ message = '数据暂缺' }) {
  return (
    <div className="rounded-xl border border-dashed border-[var(--border-color)] bg-[var(--bg-card)] px-4 py-8 text-center text-xs font-mono text-[var(--text-secondary)]">
      {message.toUpperCase()}
    </div>
  );
}

export function DataCard({ title, icon: Icon, children }) {
  return (
    <section className="rounded-xl border border-[var(--border-color)] bg-gradient-to-b from-slate-50/40 to-white/20 p-5 shadow-xl">
      <div className="mb-4 flex items-center gap-2 border-b border-[var(--border-color)] pb-3">
        {Icon && <Icon className="h-4 w-4 text-emerald-400" />}
        <h3 className="text-xs font-bold tracking-wider text-[var(--text-primary)] font-sans uppercase">{title}</h3>
      </div>
      {children}
    </section>
  );
}
