/**
 * 交易按钮 — 点击弹出 TradeModal
 */
import { useState } from 'react';
import TradeModal from './TradeModal';

/**
 * @param {object} props
 * @param {string} props.code - 股票代码 (6位)
 * @param {string} [props.name] - 股票名称
 * @param {'buy'|'sell'} [props.defaultAction] - 默认方向
 * @param {'sm'|'xs'} [props.size]
 * @param {string} [props.className]
 */
export default function TradeButton({ code, name, defaultAction = 'buy', size = 'xs', className = '' }) {
  const [open, setOpen] = useState(false);
  if (!code) return null;

  const sm = size === 'xs' ? 'text-[11px] px-1.5 py-0.5' : 'text-xs px-2 py-1';

  return (
    <>
      <div className="inline-flex gap-0.5">
        <button
          type="button"
          onClick={(e) => { e.stopPropagation(); setOpen({ action: 'buy' }); }}
          className={`rounded-l border border-red-400/50 bg-red-50 text-red-500 hover:bg-red-100 ${sm} ${className}`}
        >
          买
        </button>
        <button
          type="button"
          onClick={(e) => { e.stopPropagation(); setOpen({ action: 'sell' }); }}
          className={`rounded-r border border-green-400/50 bg-green-50 text-green-500 hover:bg-green-100 ${sm} ${className}`}
        >
          卖
        </button>
      </div>
      {open && (
        <TradeModal
          code={code}
          name={name}
          defaultAction={open.action}
          onClose={() => setOpen(false)}
        />
      )}
    </>
  );
}
