import { motion } from 'framer-motion';
import { Gauge } from 'lucide-react';
import { RadialBarChart, RadialBar, ResponsiveContainer, PolarAngleAxis } from 'recharts';

const STAGES = ['冰点', '修复', '发酵', '高潮', '分歧', '退潮'];

function calcStageIndex(score) {
  if (score < 15) return 0;
  if (score < 30) return 1;
  if (score < 50) return 2;
  if (score < 70) return 3;
  if (score < 85) return 4;
  return 5;
}

function StatBox({ label, value, tone = 'text-[var(--text-primary)]' }) {
  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-4 py-3 text-center">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--text-secondary)]">{label}</div>
      <div className={`mt-2 text-2xl font-bold ${tone}`}>{value}</div>
    </div>
  );
}

export default function EmotionGauge({ emotion, loading }) {
  const score = Number(emotion?.score || 0);
  const index = calcStageIndex(score);
  const stage = emotion?.stage || STAGES[index] || '未知';
  const stageLabel = emotion?.display_stage || emotion?.stage_label || (score >= 60 ? '发酵扩散偏高潮' : `${stage}阶段`);
  const explanation = emotion?.explain || emotion?.description || '情绪仍在扩散，分歧中更适合围绕核心低吸。';

  return (
    <motion.section
      id="emotion-panel"
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35, delay: 0.05 }}
      className="glass-card rounded-[28px] p-5"
    >
      <div className="mb-4 flex items-center justify-between">
        <div>
          <div className="text-sm font-semibold uppercase tracking-[0.24em] text-cyan-600/80">Emotion Cycle</div>
          <div className="mt-1 text-[18px] font-semibold text-[var(--text-primary)]">情绪分析</div>
        </div>
        <Gauge className="h-5 w-5 text-cyan-600" />
      </div>

      {loading ? (
        <div className="space-y-4">
          <div className="h-48 animate-pulse rounded-[24px] bg-[var(--bg-surface)]" />
          <div className="grid grid-cols-3 gap-3">
            {[...Array(3)].map((_, index) => <div key={index} className="h-20 animate-pulse rounded-2xl bg-[var(--bg-surface)]" />)}
          </div>
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-[1.05fr_0.95fr]">
          <div className="rounded-[24px] border border-[var(--border-color)] bg-[var(--bg-surface)] p-4">
            <div className="mx-auto h-44 max-w-[360px]">
              <ResponsiveContainer width="100%" height="100%">
                <RadialBarChart
                  innerRadius="72%"
                  outerRadius="100%"
                  startAngle={180}
                  endAngle={0}
                  data={[{ name: 'emotion', value: score }]}
                >
                  <PolarAngleAxis type="number" domain={[0, 100]} tick={false} />
                  <RadialBar dataKey="value" cornerRadius={20} fill="var(--accent-cyan)" background />
                </RadialBarChart>
              </ResponsiveContainer>
            </div>
            <div className="text-center">
              <div className="text-4xl font-bold text-[var(--text-primary)]">{score}</div>
              <div className="mt-2 text-sm text-[var(--text-secondary)]">{stage}</div>
            </div>
          </div>

          <div className="space-y-3">
            <div className="rounded-[24px] border border-[var(--border-color)] bg-[var(--bg-surface)] px-4 py-4">
              <div className="text-xs uppercase tracking-[0.2em] text-[var(--text-secondary)]">情绪阶段</div>
              <div className="mt-2 text-[24px] font-bold leading-tight text-[var(--text-primary)]">
                {stageLabel}
              </div>
              <div className="mt-2 text-sm leading-6 text-[var(--text-secondary)]">{explanation}</div>
              <div className="mt-3 flex flex-wrap gap-2">
                {STAGES.map((item, idx) => (
                  <span
                    key={item}
                    className={`rounded-full border px-3 py-1 text-xs font-semibold ${
                      idx === index
                        ? 'border-cyan-400/30 bg-cyan-50 text-cyan-700'
                        : 'border-[var(--border-color)] bg-[var(--bg-surface)] text-[var(--text-secondary)]'
                    }`}
                  >
                    {item}
                  </span>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-3 gap-3">
              <StatBox label="涨停数" value={emotion?.limit_up ?? 0} />
              <StatBox label="炸板数" value={emotion?.broken ?? 0} tone="text-amber-600" />
              <StatBox label="跌停数" value={emotion?.limit_down ?? 0} tone="text-rose-600" />
            </div>
          </div>
        </div>
      )}
    </motion.section>
  );
}
