/**
 * 模拟盘交易页面 — 账户总览 + 持仓列表 + 买卖下单
 */
import { useState, useEffect, useCallback, useRef } from 'react';
import { RefreshCw, Wallet, TrendingUp, PieChart, DollarSign, BarChart3 } from 'lucide-react';
import { fmtPct, fmtMoney, fmtNum, fmtRatio, pctColor } from '../utils/format';
import StockLinks from '../components/StockLinks';
import StageBar from '../components/StageBar';
import TradeButton from '../components/TradeButton';

/* ---------- helpers ---------- */

function pickNumber(...values) {
  for (const v of values) {
    if (v === null || v === undefined || v === '') continue;
    const n = Number(v);
    if (Number.isFinite(n)) return n;
  }
  return 0;
}

/* ---------- Account Overview Card ---------- */

function StatCard({ icon: Icon, label, value, color, sub }) {
  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4 flex flex-col gap-1.5">
      <div className="flex items-center gap-2 text-xs text-[var(--text-muted)]">
        <Icon className="h-3.5 w-3.5" style={{ color }} />
        <span>{label}</span>
      </div>
      <div className="text-lg font-bold font-mono tracking-tight" style={{ color: color || 'var(--text-primary)' }}>
        {value}
      </div>
      {sub && <div className="text-[10px] text-[var(--text-muted)]">{sub}</div>}
    </div>
  );
}

/* ---------- Balance Skeleton ---------- */

function BalanceSkeleton() {
  return (
    <div className="grid grid-cols-5 gap-3 animate-pulse">
      {[1, 2, 3, 4, 5].map((i) => (
        <div key={i} className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4">
          <div className="h-3 w-16 bg-[var(--border-color)] rounded mb-3" />
          <div className="h-6 w-24 bg-[var(--border-color)] rounded" />
        </div>
      ))}
    </div>
  );
}

/* ---------- Position Row Skeleton ---------- */

function PositionSkeleton() {
  return (
    <div className="animate-pulse space-y-2">
      {[1, 2, 3, 4].map((i) => (
        <div key={i} className="flex items-center gap-3 rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] px-4 py-3">
          <div className="h-4 w-20 bg-[var(--border-color)] rounded" />
          <div className="h-4 w-12 bg-[var(--border-color)] rounded" />
          <div className="h-4 w-16 bg-[var(--border-color)] rounded" />
          <div className="h-4 w-16 bg-[var(--border-color)] rounded" />
          <div className="h-4 w-20 bg-[var(--border-color)] rounded" />
          <div className="flex-1" />
          <div className="h-4 w-24 bg-[var(--border-color)] rounded" />
          <div className="h-6 w-12 bg-[var(--border-color)] rounded" />
        </div>
      ))}
    </div>
  );
}

/* ---------- Main Component ---------- */

export default function MockTradingPage({ embedded, ...props }) {
  const [balance, setBalance] = useState(null);
  const [positions, setPositions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [refreshing, setRefreshing] = useState(false);
  const timerRef = useRef(null);
  const mountedRef = useRef(true);

  const fetchData = useCallback(async (showRefreshIndicator = false) => {
    try {
      if (showRefreshIndicator) setRefreshing(true);
      else setLoading(true);
      setError('');

      const [balRes, posRes] = await Promise.all([
        fetch('/api/mock-trading/balance'),
        fetch('/api/mock-trading/positions'),
      ]);

      if (!balRes.ok || !posRes.ok) {
        throw new Error(`请求失败 (${balRes.status}/${posRes.status})`);
      }

      const balData = await balRes.json();
      const posData = await posRes.json();

      if (!mountedRef.current) return;

      setBalance(balData.data || balData);
      setPositions(posData.data?.posList || posData.posList || []);
    } catch (e) {
      if (mountedRef.current) setError(e.message || '获取数据失败');
    } finally {
      if (mountedRef.current) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  }, []);

  // Initial fetch + auto-refresh every 30s
  useEffect(() => {
    mountedRef.current = true;
    fetchData();

    timerRef.current = setInterval(() => {
      fetchData(true);
    }, 30000);

    return () => {
      mountedRef.current = false;
      clearInterval(timerRef.current);
    };
  }, [fetchData]);

  // Calculate derived values
  const b = balance || {};
  const totalAssets = pickNumber(b.totalAssets, b.data_totalAssets);
  const availBalance = pickNumber(b.availBalance, b.data_availBalance);
  const totalPosValue = pickNumber(b.totalPosValue, b.data_totalPosValue);
  const initMoney = pickNumber(b.initMoney, b.data_initMoney);
  const totalPosPct = pickNumber(b.totalPosPct, b.data_totalPosPct);

  const totalProfit = totalAssets - initMoney;
  const totalProfitPct = initMoney > 0 ? (totalProfit / initMoney) * 100 : 0;

  /* ---------- Render ---------- */
  return (
    <div className="space-y-4" {...props}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Wallet className="h-4 w-4 text-cyan-500" />
          <h1 className="text-sm font-bold text-[var(--text-primary)] tracking-wide">模拟交易</h1>
          {refreshing && (
            <RefreshCw className="h-3 w-3 text-[var(--text-muted)] animate-spin" />
          )}
        </div>
        <button
          onClick={() => fetchData(true)}
          disabled={refreshing}
          className="flex items-center gap-1 rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] px-2.5 py-1 text-[11px] text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors disabled:opacity-50"
        >
          <RefreshCw className={`h-3 w-3 ${refreshing ? 'animate-spin' : ''}`} />
          刷新
        </button>
      </div>

      {/* Error banner */}
      {error && (
        <div className="rounded-lg bg-red-50 border border-red-200 px-3 py-2 text-xs text-red-500">
          {error}
        </div>
      )}

      {/* Account Overview */}
      {loading && !balance ? (
        <BalanceSkeleton />
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          <StatCard
            icon={DollarSign}
            label="总资产"
            value={`¥${fmtMoney(totalAssets)}`}
            color="var(--text-primary)"
            sub={initMoney > 0 ? `本金 ¥${fmtMoney(initMoney)}` : null}
          />
          <StatCard
            icon={BarChart3}
            label="可用资金"
            value={`¥${fmtMoney(availBalance)}`}
            color="#22d3ee"
          />
          <StatCard
            icon={TrendingUp}
            label="持仓市值"
            value={`¥${fmtMoney(totalPosValue)}`}
            color="#60a5fa"
          />
          <StatCard
            icon={PieChart}
            label="总盈亏"
            value={`¥${fmtMoney(totalProfit)}`}
            color={totalProfit >= 0 ? '#ef4444' : '#22c55e'}
            sub={
              <span className={pctColor(totalProfitPct)}>
                {fmtPct(totalProfitPct)}
              </span>
            }
          />
          <StatCard
            icon={BarChart3}
            label="仓位比例"
            value={fmtRatio(totalPosPct)}
            color="#c084fc"
          />
        </div>
      )}

      {/* Position List */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
        <div className="px-4 py-2.5 border-b border-[var(--border-color)] flex items-center justify-between">
          <div className="flex items-center gap-2">
            <TrendingUp className="h-3.5 w-3.5 text-[var(--text-muted)]" />
            <span className="text-xs font-semibold text-[var(--text-primary)]">
              持仓明细
            </span>
            <span className="text-[10px] text-[var(--text-muted)]">
              {positions.length} 只
            </span>
          </div>
          <span className="text-[10px] text-[var(--text-muted)]">
            自动刷新每30秒
          </span>
        </div>

        {loading && !positions.length ? (
          <PositionSkeleton />
        ) : positions.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-[var(--text-muted)]">
            <Wallet className="h-8 w-8 mb-2 opacity-30" />
            <span className="text-xs">暂无持仓</span>
            <span className="text-[10px] mt-1 opacity-60">使用「智能选股」发现交易机会</span>
          </div>
        ) : (
          <div className="overflow-x-auto scrollbar-thin">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)]">
                  <th className="text-left px-4 py-2.5 font-medium">股票</th>
                  <th className="text-right px-3 py-2.5 font-medium">持仓数量</th>
                  <th className="text-right px-3 py-2.5 font-medium">成本价</th>
                  <th className="text-right px-3 py-2.5 font-medium">现价</th>
                  <th className="text-right px-3 py-2.5 font-medium">盈亏</th>
                  <th className="text-right px-3 py-2.5 font-medium">盈亏%</th>
                  <th className="text-left px-3 py-2.5 font-medium min-w-[120px]">阶段</th>
                  <th className="text-center px-3 py-2.5 font-medium">操作</th>
                </tr>
              </thead>
              <tbody>
                {positions.map((pos, idx) => {
                  const code = String(pos.secCode || '').padStart(6, '0');
                  const name = pos.secName || '--';
                  const count = pickNumber(pos.count, pos.position);
                  const costPrice = pickNumber(pos.costPrice, pos.price);
                  const costPriceDec = pickNumber(pos.costPriceDec, pos.priceDec, 2);
                  const curPrice = pickNumber(pos.price);
                  const priceDec = pickNumber(pos.priceDec, 2);
                  const profit = pickNumber(pos.profit);
                  const profitPct = pickNumber(pos.profitPct);

                  return (
                    <tr
                      key={code || idx}
                      className="border-b border-[var(--border-color)] last:border-b-0 hover:bg-[var(--bg-surface)]/50 transition-colors"
                    >
                      {/* 股票 */}
                      <td className="px-4 py-2.5">
                        <div className="flex flex-col">
                          <div className="flex items-center gap-1">
                            <span className="font-medium text-[var(--text-primary)] text-sm">{name}</span>
                            <span className="text-[10px] font-mono text-[var(--text-muted)]">{code}</span>
                          </div>
                          <StockLinks code={code} />
                        </div>
                      </td>

                      {/* 持仓数量 */}
                      <td className="text-right px-3 py-2.5 font-mono text-[var(--text-primary)]">
                        {fmtNum(count)}
                      </td>

                      {/* 成本价 */}
                      <td className="text-right px-3 py-2.5 font-mono text-[var(--text-secondary)]">
                        {costPrice.toFixed(costPriceDec)}
                      </td>

                      {/* 现价 */}
                      <td className="text-right px-3 py-2.5">
                        <span className="font-mono text-[var(--text-primary)]">
                          {curPrice.toFixed(priceDec)}
                        </span>
                      </td>

                      {/* 盈亏 */}
                      <td className="text-right px-3 py-2.5">
                        <span className={`font-mono font-medium ${pctColor(profit)}`}>
                          {profit >= 0 ? '+' : ''}¥{fmtMoney(Math.abs(profit))}
                        </span>
                      </td>

                      {/* 盈亏% */}
                      <td className="text-right px-3 py-2.5">
                        <span className={`font-mono font-medium ${pctColor(profitPct)}`}>
                          {fmtPct(profitPct)}
                        </span>
                      </td>

                      {/* 阶段 */}
                      <td className="px-3 py-2.5">
                        <StageBar profitPct={profitPct} />
                      </td>

                      {/* 操作 */}
                      <td className="text-center px-3 py-2.5">
                        <TradeButton code={code} name={name} />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="text-[10px] text-[var(--text-muted)] text-center opacity-50">
        模拟交易系统 · 数据仅供测试参考
      </div>
    </div>
  );
}
