/**
 * 交易下单弹窗 — 支持买入/卖出，市价/限价
 */
import { useState, useEffect, useCallback } from 'react';
import { X } from 'lucide-react';
import { fmtPrice } from '../utils/format';

export default function TradeModal({ code, name, defaultAction = 'buy', onClose }) {
  const [action, setAction] = useState(defaultAction);
  const [orderType, setOrderType] = useState('market'); // 'market' | 'limit'
  const [price, setPrice] = useState('');
  const [quantity, setQuantity] = useState(100);
  const [quote, setQuote] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState(null);

  // Fetch real-time quote
  useEffect(() => {
    fetch(`/api/mock-trading/quote?code=${code}`)
      .then((r) => r.json())
      .then((d) => setQuote(d))
      .catch(() => setQuote(null));
  }, [code]);

  const currentPrice = quote ? fmtPrice(quote.price, quote.priceDec) : '--';
  const costPrice = quote ? fmtPrice(quote.costPrice, quote.costPriceDec) : '--';

  // Price validation
  const limitUp = quote ? fmtPrice(quote.limitUp, 2) : null;
  const limitDown = quote ? fmtPrice(quote.limitDown, 2) : null;

  const handleSubmit = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const body = {
        type: action === 'buy' ? 'buy' : 'sell',
        stockCode: code,
        quantity,
      };
      if (orderType === 'limit') {
        body.price = Number(price);
      }

      const res = await fetch('/api/mock-trading/trade', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const data = await res.json();
      if (res.ok && (data.code === '200' || data.status === 0 || data.data?.result?.status === 0)) {
        setResult({ ok: true, msg: '下单成功' });
        setTimeout(onClose, 1500);
      } else {
        setResult({ ok: false, msg: data.message || data.msg || '下单失败' });
      }
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, [action, code, quantity, orderType, price, onClose]);

  // Quick quantity buttons
  const quickQtys = action === 'buy'
    ? [100, 200, 500, 1000]
    : [100, 200, 500, 1000];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50" onClick={onClose}>
      <div
        className="w-full max-w-sm rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-5 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <span
              className={`inline-flex items-center rounded px-2 py-0.5 text-sm font-bold ${
                action === 'buy' ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-500'
              }`}
            >
              {action === 'buy' ? '买入' : '卖出'}
            </span>
            <span className="text-sm font-semibold text-[var(--text-primary)]">{name || code}</span>
            <span className="text-xs font-mono text-[var(--text-muted)]">{code}</span>
          </div>
          <button onClick={onClose} className="text-[var(--text-muted)] hover:text-[var(--text-primary)]">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Quote line */}
        <div className="flex items-center gap-3 mb-3 text-xs text-[var(--text-secondary)]">
          <span>现价: <span className="font-mono font-semibold text-[var(--text-primary)]">{currentPrice}</span></span>
          <span>成本: <span className="font-mono">{costPrice}</span></span>
        </div>

        {/* Order type toggle */}
        <div className="flex gap-2 mb-3">
          <button
            onClick={() => setOrderType('market')}
            className={`flex-1 rounded-lg py-1.5 text-xs font-medium transition-colors ${
              orderType === 'market'
                ? 'bg-cyan-600 text-white'
                : 'bg-[var(--bg-surface)] text-[var(--text-muted)]'
            }`}
          >
            市价
          </button>
          <button
            onClick={() => setOrderType('limit')}
            className={`flex-1 rounded-lg py-1.5 text-xs font-medium transition-colors ${
              orderType === 'limit'
                ? 'bg-cyan-600 text-white'
                : 'bg-[var(--bg-surface)] text-[var(--text-muted)]'
            }`}
          >
            限价
          </button>
        </div>

        {/* Price (limit only) */}
        {orderType === 'limit' && (
          <div className="mb-3">
            <label className="block text-xs text-[var(--text-muted)] mb-1">价格</label>
            <input
              type="number"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              placeholder={`输入价格`}
              className="w-full rounded-lg border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1.5 text-sm text-[var(--text-primary)] focus:outline-none focus:border-cyan-600"
              step="0.01"
            />
            {limitUp && limitDown && (
              <div className="flex justify-between text-[10px] text-[var(--text-muted)] mt-0.5">
                <span>跌停: {limitDown}</span>
                <span>涨停: {limitUp}</span>
              </div>
            )}
          </div>
        )}

        {/* Quantity */}
        <div className="mb-3">
          <label className="block text-xs text-[var(--text-muted)] mb-1">数量</label>
          <input
            type="number"
            value={quantity}
            onChange={(e) => setQuantity(Math.max(100, Number(e.target.value)))}
            className="w-full rounded-lg border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1.5 text-sm text-[var(--text-primary)] focus:outline-none focus:border-cyan-600"
            min={100}
            step={100}
          />
        </div>

        {/* Quick buttons */}
        <div className="flex gap-1 mb-3">
          {quickQtys.map((q) => (
            <button
              key={q}
              onClick={() => setQuantity(q)}
              className={`flex-1 rounded py-1 text-[10px] font-medium transition-colors ${
                quantity === q
                  ? 'bg-cyan-600 text-white'
                  : 'bg-[var(--bg-surface)] text-[var(--text-muted)] hover:text-[var(--text-primary)]'
              }`}
            >
              {q}股
            </button>
          ))}
        </div>

        {/* Error */}
        {error && (
          <div className="mb-2 text-xs text-red-400 bg-red-50 rounded px-2 py-1">{error}</div>
        )}

        {/* Result */}
        {result && (
          <div
            className={`mb-2 text-xs rounded px-2 py-1 ${
              result.ok ? 'bg-emerald-50 text-emerald-500' : 'bg-red-50 text-red-400'
            }`}
          >
            {result.msg}
          </div>
        )}

        {/* Submit */}
        <button
          onClick={handleSubmit}
          disabled={loading || (orderType === 'limit' && !price)}
          className={`w-full rounded-lg py-2 text-sm font-bold transition-colors ${
            action === 'buy'
              ? 'bg-red-500 text-white hover:bg-red-400'
              : 'bg-green-500 text-white hover:bg-green-400'
          } disabled:opacity-50 disabled:cursor-not-allowed`}
        >
          {loading ? '提交中...' : action === 'buy' ? '买入' : '卖出'}
        </button>
      </div>
    </div>
  );
}
