import { useEffect, useState, useRef } from 'react';

// 模块级缓存：组件卸载后再挂载时立刻可用，无需等待网络
let _cachedStrategies = {};
let _cachedAt = 0;
const CACHE_STALE_MS = 120_000; // 2 分钟内视为新鲜

export function useRobotStrategies() {
  const hasCache = _cachedAt > 0 && Object.keys(_cachedStrategies).length > 0;
  const [strategies, setStrategies] = useState(hasCache ? _cachedStrategies : {});
  const [loading, setLoading] = useState(!hasCache); // 有缓存就不显示 loading
  const [error, setError] = useState('');
  const mountedRef = useRef(true);

  const fetchStrategies = async (silent = false) => {
    try {
      if (silent) {
        // 静默刷新：不触发 loading spinner
      } else {
        setLoading(true);
      }
      const response = await fetch('/api/ops/robot-strategies');
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }
      const data = await response.json();
      if (!mountedRef.current) return;
      setStrategies(data);
      _cachedStrategies = data;
      _cachedAt = Date.now();
      setError('');
    } catch (err) {
      if (!mountedRef.current) return;
      setError('无法获取机器人策略结果');
    } finally {
      if (mountedRef.current) setLoading(false);
    }
  };

  useEffect(() => {
    mountedRef.current = true;
    const isFresh = _cachedAt > 0 && (Date.now() - _cachedAt) < CACHE_STALE_MS;
    if (isFresh) {
      // 缓存新鲜：直接用缓存，后台静默刷新
      setStrategies(_cachedStrategies);
      setLoading(false);
      fetchStrategies(true);
    } else {
      // 缓存过期或无缓存：正常加载
      fetchStrategies(false);
    }
    // 每60秒刷新
    const interval = setInterval(() => fetchStrategies(true), 60000);
    return () => {
      mountedRef.current = false;
      clearInterval(interval);
    };
  }, []);

  return {
    strategies,
    loading,
    error,
    refresh: () => fetchStrategies(false),
  };
}
